// Réglages du suivi des artisans (brief : plans/011-cadrage-01-11/briefs/c4-n8n-suivi-artisan.md). Mode brouillon : rien ne part.
// Jours comptés au jour de Paris. Fenêtres, heure, écart et plafond : défauts du lot, à valider par Benj.
const jour = $now.setZone('Europe/Paris').toISODate();
const decaler = (j, n) => new Date(Date.parse(j + 'T00:00:00Z') + n * 86400000).toISOString().slice(0, 10);
return [{ json: {
  jour,
  mode: 'brouillon',
  mention_ia: 'non_vise',
  offres_suivies: ['studio', 'signature', 'entreprise'],
  etapes: {
    premiers_pas: { du: 0, au: 3, evenements_jusqu_a: 2 },
    bilan_j14: { du: 14, au: 16 },
    bilan_j30: { du: 30, au: 32 }
  },
  ecart_min_jours: 5,
  plafond_par_passage: 10,
  inscrits_depuis: decaler(jour, -34)
} }];

// Départ du suivi : les comptes lus, écartés DANS LE CODE aussi (la requête filtre déjà) : démo, fondateur, suppression demandée,
// offre hors du suivi, opposition au suivi (notifications.suivi === false ; absent = activé, comme notificationActive,
// lib/notificationsTypes.ts:16-18). Une colonne absente ou illisible écarte le compte (refus par défaut).
const R = $('Réglages du suivi').first().json;
const lignes = (nom) => $(nom).all().map((i) => i.json).filter((r) => r && typeof r === 'object' && Object.keys(r).length > 0);
const jourParis = (v) => {
  if (typeof v !== 'string' || v.length < 10) return null;
  const d = new Date(v);
  if (Number.isNaN(d.getTime())) return null;
  const p = {};
  for (const x of new Intl.DateTimeFormat('en-GB', { timeZone: 'Europe/Paris', year: 'numeric', month: '2-digit', day: '2-digit' }).formatToParts(d)) p[x.type] = x.value;
  return p.year + '-' + p.month + '-' + p.day;
};
const ecart = (a, b) => Math.round((Date.parse(a + 'T00:00:00Z') - Date.parse(b + 'T00:00:00Z')) / 86400000);
const ecartes = {};
const ecarter = (motif) => { ecartes[motif] = (ecartes[motif] || 0) + 1; };
const comptes = [];
const vus = new Set();
for (const a of lignes('Lire comptes')) {
  if (typeof a.id !== 'string' || vus.has(a.id)) continue;
  vus.add(a.id);
  if (a.est_demo !== false) { ecarter('demo'); continue; }
  if (a.is_founder !== false) { ecarter('fondateur'); continue; }
  if (a.suppression_demandee_le !== null) { ecarter('suppression_demandee'); continue; }
  if (!R.offres_suivies.includes(a.plan)) { ecarter('hors_offre'); continue; }
  const n = a.notifications;
  if (n !== null && n !== undefined && (typeof n !== 'object' || n.suivi === false)) { ecarter('opposition_suivi'); continue; }
  const inscription = jourParis(a.created_at);
  if (!inscription) { ecarter('inscription_illisible'); continue; }
  const age = ecart(R.jour, inscription);
  if (age < 0) { ecarter('inscription_illisible'); continue; }
  comptes.push({ artisan_id: a.id, inscription, age });
}
return [{ json: { comptes, ecartes, candidats: [], silencieux: {} } }];

// Étape premiers_pas (J0 à J+2) : au plus un message, né de la PREMIÈRE réussite réelle des premiers jours (première demande reçue,
// premier devis envoyé ou accepté, première facture émise). L'inscription seule ne fait rien écrire (le premier contact passe par
// « Découvrir »). Une demande importée (canal 'import', lib/canaux/regles.ts:34) n'est pas une demande reçue ; ni un avoir ni une
// facture annulée ne sont une facture émise.
const R = $('Réglages du suivi').first().json;
const E = R.etapes.premiers_pas;
const etat = $input.first().json;
const lignes = (nom) => $(nom).all().map((i) => i.json).filter((r) => r && typeof r === 'object' && Object.keys(r).length > 0);
const jourParis = (v) => {
  if (typeof v !== 'string' || v.length < 10) return null;
  const d = new Date(v);
  if (Number.isNaN(d.getTime())) return null;
  const p = {};
  for (const x of new Intl.DateTimeFormat('en-GB', { timeZone: 'Europe/Paris', year: 'numeric', month: '2-digit', day: '2-digit' }).formatToParts(d)) p[x.type] = x.value;
  return p.year + '-' + p.month + '-' + p.day;
};
const ecart = (a, b) => Math.round((Date.parse(a + 'T00:00:00Z') - Date.parse(b + 'T00:00:00Z')) / 86400000);
const dansLaFenetre = etat.comptes.filter((c) => c.age >= E.du && c.age <= E.au);
const parCompte = new Map(dansLaFenetre.map((c) => [c.artisan_id, c]));
const reussites = new Map();
const ajouter = (artisanId, table, id, colonne, date, ordre, variante) => {
  const c = parCompte.get(artisanId);
  if (!c || typeof id !== 'string') return;
  const j = jourParis(date);
  if (!j) return;
  const d = ecart(j, c.inscription);
  if (d < 0 || d > E.evenements_jusqu_a || d > c.age) return;
  const l = reussites.get(artisanId) || [];
  l.push({ t: Date.parse(date), ordre, variante, evenement: { table, id, colonne, date } });
  reussites.set(artisanId, l);
};
for (const l of lignes('Lire demandes')) if (l.canal !== 'import') ajouter(l.artisan_id, 'leads', l.id, 'created_at', l.created_at, 0, 'premiere_demande');
for (const l of lignes('Lire devis')) {
  if (l.envoye_le) ajouter(l.artisan_id, 'devis', l.id, 'envoye_le', l.envoye_le, 1, 'premier_devis_envoye');
  if (l.accepte_le) ajouter(l.artisan_id, 'devis', l.id, 'accepte_le', l.accepte_le, 2, 'premier_devis_accepte');
}
for (const l of lignes('Lire factures')) {
  if (l.emise_le && (l.statut === 'emise' || l.statut === 'payee') && l.avoir_de === null) ajouter(l.artisan_id, 'factures', l.id, 'emise_le', l.emise_le, 3, 'premiere_facture');
}
const candidats = [];
let silencieux = 0;
for (const c of dansLaFenetre) {
  const l = reussites.get(c.artisan_id);
  if (!l || !l.length) { silencieux += 1; continue; }
  l.sort((a, b) => a.t - b.t || a.ordre - b.ordre || (a.evenement.id < b.evenement.id ? -1 : a.evenement.id > b.evenement.id ? 1 : 0));
  const premiere = l[0];
  candidats.push({ cle: 'suivi:' + c.artisan_id + ':premiers_pas', artisan_id: c.artisan_id, etape: 'premiers_pas', variante: premiere.variante,
    champs: {}, evenements: [premiere.evenement], reste: E.au - c.age, inscription: c.inscription });
}
const s = Object.assign({}, etat.silencieux);
s.premiers_pas = silencieux;
return [{ json: { comptes: etat.comptes, ecartes: etat.ecartes, candidats: etat.candidats.concat(candidats), silencieux: s } }];

// Étape bilan_j14 : les comptes réels depuis l'inscription (demandes reçues, devis envoyés, devis acceptés, factures émises). Une demande
// importée (canal 'import', lib/canaux/regles.ts:34) n'est pas une demande reçue ; ni un avoir ni une facture annulée ne sont une
// facture émise. Sans aucun événement, aucun message : le compte est compté « silencieux ».
const ETAPE = 'bilan_j14';
const R = $('Réglages du suivi').first().json;
const E = R.etapes[ETAPE];
const etat = $input.first().json;
const lignes = (nom) => $(nom).all().map((i) => i.json).filter((r) => r && typeof r === 'object' && Object.keys(r).length > 0);
const jourParis = (v) => {
  if (typeof v !== 'string' || v.length < 10) return null;
  const d = new Date(v);
  if (Number.isNaN(d.getTime())) return null;
  const p = {};
  for (const x of new Intl.DateTimeFormat('en-GB', { timeZone: 'Europe/Paris', year: 'numeric', month: '2-digit', day: '2-digit' }).formatToParts(d)) p[x.type] = x.value;
  return p.year + '-' + p.month + '-' + p.day;
};
const ecart = (a, b) => Math.round((Date.parse(a + 'T00:00:00Z') - Date.parse(b + 'T00:00:00Z')) / 86400000);
const dansLaFenetre = etat.comptes.filter((c) => c.age >= E.du && c.age <= E.au);
const parCompte = new Map(dansLaFenetre.map((c) => [c.artisan_id, { c, champs: { demandes_recues: 0, devis_envoyes: 0, devis_acceptes: 0, factures_emises: 0 }, evenements: [] }]));
const compter = (artisanId, champ, table, id, colonne, date) => {
  const x = parCompte.get(artisanId);
  if (!x || typeof id !== 'string') return;
  const j = jourParis(date);
  if (!j) return;
  const d = ecart(j, x.c.inscription);
  if (d < 0 || d > x.c.age) return;
  x.champs[champ] += 1;
  x.evenements.push({ table, id, colonne, date });
};
for (const l of lignes('Lire demandes')) if (l.canal !== 'import') compter(l.artisan_id, 'demandes_recues', 'leads', l.id, 'created_at', l.created_at);
for (const l of lignes('Lire devis')) {
  if (l.envoye_le) compter(l.artisan_id, 'devis_envoyes', 'devis', l.id, 'envoye_le', l.envoye_le);
  if (l.accepte_le) compter(l.artisan_id, 'devis_acceptes', 'devis', l.id, 'accepte_le', l.accepte_le);
}
for (const l of lignes('Lire factures')) {
  if (l.emise_le && (l.statut === 'emise' || l.statut === 'payee') && l.avoir_de === null) compter(l.artisan_id, 'factures_emises', 'factures', l.id, 'emise_le', l.emise_le);
}
const candidats = [];
let silencieux = 0;
for (const x of parCompte.values()) {
  if (!x.evenements.length) { silencieux += 1; continue; }
  candidats.push({ cle: 'suivi:' + x.c.artisan_id + ':' + ETAPE, artisan_id: x.c.artisan_id, etape: ETAPE, variante: 'comptes',
    champs: x.champs, evenements: x.evenements, reste: E.au - x.c.age, inscription: x.c.inscription });
}
const s = Object.assign({}, etat.silencieux);
s[ETAPE] = silencieux;
return [{ json: { comptes: etat.comptes, ecartes: etat.ecartes, candidats: etat.candidats.concat(candidats), silencieux: s } }];

// Étape bilan_j30 : les comptes réels depuis l'inscription (demandes reçues, devis envoyés, devis acceptés, factures émises). Une demande
// importée (canal 'import', lib/canaux/regles.ts:34) n'est pas une demande reçue ; ni un avoir ni une facture annulée ne sont une
// facture émise. Sans aucun événement, aucun message : le compte est compté « silencieux ».
const ETAPE = 'bilan_j30';
const R = $('Réglages du suivi').first().json;
const E = R.etapes[ETAPE];
const etat = $input.first().json;
const lignes = (nom) => $(nom).all().map((i) => i.json).filter((r) => r && typeof r === 'object' && Object.keys(r).length > 0);
const jourParis = (v) => {
  if (typeof v !== 'string' || v.length < 10) return null;
  const d = new Date(v);
  if (Number.isNaN(d.getTime())) return null;
  const p = {};
  for (const x of new Intl.DateTimeFormat('en-GB', { timeZone: 'Europe/Paris', year: 'numeric', month: '2-digit', day: '2-digit' }).formatToParts(d)) p[x.type] = x.value;
  return p.year + '-' + p.month + '-' + p.day;
};
const ecart = (a, b) => Math.round((Date.parse(a + 'T00:00:00Z') - Date.parse(b + 'T00:00:00Z')) / 86400000);
const dansLaFenetre = etat.comptes.filter((c) => c.age >= E.du && c.age <= E.au);
const parCompte = new Map(dansLaFenetre.map((c) => [c.artisan_id, { c, champs: { demandes_recues: 0, devis_envoyes: 0, devis_acceptes: 0, factures_emises: 0 }, evenements: [] }]));
const compter = (artisanId, champ, table, id, colonne, date) => {
  const x = parCompte.get(artisanId);
  if (!x || typeof id !== 'string') return;
  const j = jourParis(date);
  if (!j) return;
  const d = ecart(j, x.c.inscription);
  if (d < 0 || d > x.c.age) return;
  x.champs[champ] += 1;
  x.evenements.push({ table, id, colonne, date });
};
for (const l of lignes('Lire demandes')) if (l.canal !== 'import') compter(l.artisan_id, 'demandes_recues', 'leads', l.id, 'created_at', l.created_at);
for (const l of lignes('Lire devis')) {
  if (l.envoye_le) compter(l.artisan_id, 'devis_envoyes', 'devis', l.id, 'envoye_le', l.envoye_le);
  if (l.accepte_le) compter(l.artisan_id, 'devis_acceptes', 'devis', l.id, 'accepte_le', l.accepte_le);
}
for (const l of lignes('Lire factures')) {
  if (l.emise_le && (l.statut === 'emise' || l.statut === 'payee') && l.avoir_de === null) compter(l.artisan_id, 'factures_emises', 'factures', l.id, 'emise_le', l.emise_le);
}
const candidats = [];
let silencieux = 0;
for (const x of parCompte.values()) {
  if (!x.evenements.length) { silencieux += 1; continue; }
  candidats.push({ cle: 'suivi:' + x.c.artisan_id + ':' + ETAPE, artisan_id: x.c.artisan_id, etape: ETAPE, variante: 'comptes',
    champs: x.champs, evenements: x.evenements, reste: E.au - x.c.age, inscription: x.c.inscription });
}
const s = Object.assign({}, etat.silencieux);
s[ETAPE] = silencieux;
return [{ json: { comptes: etat.comptes, ecartes: etat.ecartes, candidats: etat.candidats.concat(candidats), silencieux: s } }];

// Garde du suivi : une clé déjà au registre ne revient pas ; jamais un e-mail du suivi à un artisan moins de 5 jours après le précédent
// (memoire-presti/un-message-par-artisan-avant-5-jours.md) ; au plus un brouillon par artisan et par passage ; au-delà du plafond, reporté :
// la fenêtre la plus proche de sa fin passe en tête, au passage suivant (même principe que .claude/rules/email-brevo.md:18).
// Une date illisible au registre compte comme un envoi du jour (refus par défaut). Si le registre ne se lit pas, le passage s'arrête avant.
const R = $('Réglages du suivi').first().json;
const etat = $input.first().json;
const lignes = (nom) => $(nom).all().map((i) => i.json).filter((r) => r && typeof r === 'object' && Object.keys(r).length > 0);
const jourParis = (v) => {
  if (typeof v !== 'string' || v.length < 10) return null;
  const d = new Date(v);
  if (Number.isNaN(d.getTime())) return null;
  const p = {};
  for (const x of new Intl.DateTimeFormat('en-GB', { timeZone: 'Europe/Paris', year: 'numeric', month: '2-digit', day: '2-digit' }).formatToParts(d)) p[x.type] = x.value;
  return p.year + '-' + p.month + '-' + p.day;
};
const ecart = (a, b) => Math.round((Date.parse(a + 'T00:00:00Z') - Date.parse(b + 'T00:00:00Z')) / 86400000);
const cles = new Set();
const dernier = new Map();
for (const r of lignes('Lire registre du suivi')) {
  if (typeof r.cle === 'string') cles.add(r.cle);
  if (typeof r.artisan_id !== 'string') continue;
  const j = jourParis(r.envoye_le) || R.jour;
  if (!dernier.has(r.artisan_id) || j > dernier.get(r.artisan_id)) dernier.set(r.artisan_id, j);
}
const ecartes = Object.assign({}, etat.ecartes);
const ecarter = (motif) => { ecartes[motif] = (ecartes[motif] || 0) + 1; };
const tries = etat.candidats.slice().sort((a, b) => a.reste - b.reste || (a.inscription < b.inscription ? -1 : a.inscription > b.inscription ? 1 : 0)
  || (a.artisan_id < b.artisan_id ? -1 : a.artisan_id > b.artisan_id ? 1 : 0) || (a.cle < b.cle ? -1 : a.cle > b.cle ? 1 : 0));
const brouillons = [];
const reportes = [];
const servis = new Set();
for (const c of tries) {
  if (cles.has(c.cle)) { ecarter('deja_au_registre'); continue; }
  const d = dernier.get(c.artisan_id);
  if (d !== undefined && ecart(R.jour, d) < R.ecart_min_jours) { ecarter('ecart_5_jours'); continue; }
  if (servis.has(c.artisan_id)) { ecarter('un_par_passage'); continue; }
  servis.add(c.artisan_id);
  if (brouillons.length >= R.plafond_par_passage) { reportes.push({ cle: c.cle, artisan_id: c.artisan_id, etape: c.etape }); continue; }
  brouillons.push({ cle: c.cle, artisan_id: c.artisan_id, etape: c.etape, variante: c.variante, champs: c.champs, evenements: c.evenements });
}
return [{ json: { brouillons, reportes, ecartes, silencieux: etat.silencieux } }];

// Textes du suivi (brouillons) : des textes FIXES, aucun appel à un modèle. Ce sont des e-mails de Presti à ses artisans (Reply-To
// contact@prestiapp.fr, lib/email.ts:6-9) : ils ne portent pas la mention d'IA (plan du chantier 4, §0 bis, mention : non visé).
// Aucun chiffre écrit : les nombres viennent des champs comptés, entre accolades. Chaque texte attend la validation de Benj.
// Les mêmes textes, mot pour mot : plans/011-cadrage-01-11/briefs/c4-n8n-suivi-artisan.md (« Les textes »).
const PIED = 'Pour ne plus recevoir ces e-mails de suivi, répondez « stop » à ce message.\n\nPresti';
const TEXTES = {
  premiers_pas: {
    premiere_demande: {
      statut: 'brouillon',
      objet: 'Une première demande : la suite',
      corps: 'Bonjour,\n\nUne première demande est arrivée sur votre page. Vous retrouvez l’échange dans Messages, et le devis se prépare depuis la même conversation.\n\nUne question en route ? Répondez simplement à cet e-mail.\n\n' + PIED
    },
    premier_devis_envoye: {
      statut: 'brouillon',
      objet: 'Votre premier devis est parti : la suite',
      corps: 'Bonjour,\n\nVotre premier devis est parti. Quand votre client l’accepte, ouvrez le devis et cliquez « Créer la facture » : les lignes sont reprises, la numérotation suit.\n\nUne question en route ? Répondez simplement à cet e-mail.\n\n' + PIED
    },
    premier_devis_accepte: {
      statut: 'brouillon',
      objet: 'Après le devis accepté : la facture',
      corps: 'Bonjour,\n\nLa suite d’un devis accepté, c’est la facture : ouvrez le devis et cliquez « Créer la facture ». Les lignes sont reprises, la numérotation suit.\n\nUne question en route ? Répondez simplement à cet e-mail.\n\n' + PIED
    },
    premiere_facture: {
      statut: 'brouillon',
      objet: 'Votre première facture : la suite',
      corps: 'Bonjour,\n\nVotre première facture est émise. Vous suivez son paiement dans Factures, avec ce qui est réglé et ce qui reste à encaisser.\n\nUne question en route ? Répondez simplement à cet e-mail.\n\n' + PIED
    }
  },
  bilan_j14: {
    comptes: {
      statut: 'brouillon',
      objet: 'Vos premières semaines sur Presti',
      corps: 'Bonjour,\n\nVoici ce qui s’est passé sur votre compte depuis votre inscription :\n\nDemandes reçues : {demandes_recues}\nDevis envoyés : {devis_envoyes}\nDevis acceptés : {devis_acceptes}\nFactures émises : {factures_emises}\n\nUne idée, une question, quelque chose qui vous manque ? Répondez simplement à cet e-mail.\n\n' + PIED
    }
  },
  bilan_j30: {
    comptes: {
      statut: 'brouillon',
      objet: 'Votre premier mois sur Presti',
      corps: 'Bonjour,\n\nVoici ce qui s’est passé sur votre compte depuis votre inscription :\n\nDemandes reçues : {demandes_recues}\nDevis envoyés : {devis_envoyes}\nDevis acceptés : {devis_acceptes}\nFactures émises : {factures_emises}\n\nUne idée, une question, quelque chose qui vous manque ? Répondez simplement à cet e-mail.\n\n' + PIED
    }
  }
};
const etat = $input.first().json;
for (const b of etat.brouillons) {
  const t = TEXTES[b.etape] && TEXTES[b.etape][b.variante];
  if (!t || t.statut !== 'brouillon') throw new Error('texte absent ou non brouillon : ' + b.etape + '.' + b.variante);
  const attendus = (t.objet + '\n' + t.corps).match(/\{[a-z_]+\}/g) || [];
  for (const a of attendus) if (!Object.prototype.hasOwnProperty.call(b.champs, a.slice(1, -1))) throw new Error('champ manquant ' + a + ' pour ' + b.cle);
}
return [{ json: { brouillons: etat.brouillons, reportes: etat.reportes, ecartes: etat.ecartes, silencieux: etat.silencieux, textes: TEXTES } }];

// Brouillons et bilan : la seule sortie. Les brouillons (identifiants, étape, variante, comptes, événements : jamais un nom, une adresse,
// un e-mail ni un texte) et un bilan agrégé par étape. Rien n'est envoyé, rien n'est écrit : l'envoi viendra après la validation des textes.
const R = $('Réglages du suivi').first().json;
const etat = $input.first().json;
const par_etape = {};
for (const e of Object.keys(R.etapes)) {
  par_etape[e] = {
    brouillons: etat.brouillons.filter((b) => b.etape === e).length,
    reportes: etat.reportes.filter((b) => b.etape === e).length,
    silencieux: etat.silencieux[e] || 0
  };
}
return [{ json: {
  mode: R.mode,
  mention_ia: R.mention_ia,
  jour: R.jour,
  bilan: { par_etape, ecartes: etat.ecartes, reportes: etat.reportes.map((r) => r.cle) },
  brouillons: etat.brouillons
} }];

// Réglages du suivi des artisans (brief : plans/011-cadrage-01-11/briefs/c4-n8n-suivi-artisan.md). Mode brouillon : rien ne part.
// Jours comptés au jour de Paris. Fenêtres, heure, écart et plafond : défauts du lot, à valider par Benj.
const jour = $now.setZone('Europe/Paris').toISODate();
const decaler = (j, n) => new Date(Date.parse(j + 'T00:00:00Z') + n * 86400000).toISOString().slice(0, 10);
return [{ json: {
  jour,
  mode: 'brouillon',
  mention_ia: 'non_vise',
  offres_suivies: ['studio', 'signature', 'entreprise'],
  etapes: {
    premiers_pas: { du: 0, au: 3, evenements_jusqu_a: 2 },
    bilan_j14: { du: 14, au: 16 },
    bilan_j30: { du: 30, au: 32 }
  },
  ecart_min_jours: 5,
  plafond_par_passage: 10,
  inscrits_depuis: decaler(jour, -34)
} }];

// Départ du suivi : les comptes lus, écartés DANS LE CODE aussi (la requête filtre déjà) : démo, fondateur, suppression demandée,
// offre hors du suivi, opposition au suivi (notifications.suivi === false ; absent = activé, comme notificationActive,
// lib/notificationsTypes.ts:16-18). Une colonne absente ou illisible écarte le compte (refus par défaut).
const R = $('Réglages du suivi').first().json;
const lignes = (nom) => $(nom).all().map((i) => i.json).filter((r) => r && typeof r === 'object' && Object.keys(r).length > 0);
const jourParis = (v) => {
  if (typeof v !== 'string' || v.length < 10) return null;
  const d = new Date(v);
  if (Number.isNaN(d.getTime())) return null;
  const p = {};
  for (const x of new Intl.DateTimeFormat('en-GB', { timeZone: 'Europe/Paris', year: 'numeric', month: '2-digit', day: '2-digit' }).formatToParts(d)) p[x.type] = x.value;
  return p.year + '-' + p.month + '-' + p.day;
};
const ecart = (a, b) => Math.round((Date.parse(a + 'T00:00:00Z') - Date.parse(b + 'T00:00:00Z')) / 86400000);
const ecartes = {};
const ecarter = (motif) => { ecartes[motif] = (ecartes[motif] || 0) + 1; };
const comptes = [];
const vus = new Set();
for (const a of lignes('Lire comptes')) {
  if (typeof a.id !== 'string' || vus.has(a.id)) continue;
  vus.add(a.id);
  if (a.est_demo !== false) { ecarter('demo'); continue; }
  if (a.is_founder !== false) { ecarter('fondateur'); continue; }
  if (a.suppression_demandee_le !== null) { ecarter('suppression_demandee'); continue; }
  if (!R.offres_suivies.includes(a.plan)) { ecarter('hors_offre'); continue; }
  const n = a.notifications;
  if (n !== null && n !== undefined && (typeof n !== 'object' || n.suivi === false)) { ecarter('opposition_suivi'); continue; }
  const inscription = jourParis(a.created_at);
  if (!inscription) { ecarter('inscription_illisible'); continue; }
  const age = ecart(R.jour, inscription);
  if (age < 0) { ecarter('inscription_illisible'); continue; }
  comptes.push({ artisan_id: a.id, inscription, age });
}
return [{ json: { comptes, ecartes, candidats: [], silencieux: {} } }];

// Étape premiers_pas (J0 à J+2) : au plus un message, né de la PREMIÈRE réussite réelle des premiers jours (première demande reçue,
// premier devis envoyé ou accepté, première facture émise). L'inscription seule ne fait rien écrire (le premier contact passe par
// « Découvrir »). Une demande importée (canal 'import', lib/canaux/regles.ts:34) n'est pas une demande reçue ; ni un avoir ni une
// facture annulée ne sont une facture émise.
const R = $('Réglages du suivi').first().json;
const E = R.etapes.premiers_pas;
const etat = $input.first().json;
const lignes = (nom) => $(nom).all().map((i) => i.json).filter((r) => r && typeof r === 'object' && Object.keys(r).length > 0);
const jourParis = (v) => {
  if (typeof v !== 'string' || v.length < 10) return null;
  const d = new Date(v);
  if (Number.isNaN(d.getTime())) return null;
  const p = {};
  for (const x of new Intl.DateTimeFormat('en-GB', { timeZone: 'Europe/Paris', year: 'numeric', month: '2-digit', day: '2-digit' }).formatToParts(d)) p[x.type] = x.value;
  return p.year + '-' + p.month + '-' + p.day;
};
const ecart = (a, b) => Math.round((Date.parse(a + 'T00:00:00Z') - Date.parse(b + 'T00:00:00Z')) / 86400000);
const dansLaFenetre = etat.comptes.filter((c) => c.age >= E.du && c.age <= E.au);
const parCompte = new Map(dansLaFenetre.map((c) => [c.artisan_id, c]));
const reussites = new Map();
const ajouter = (artisanId, table, id, colonne, date, ordre, variante) => {
  const c = parCompte.get(artisanId);
  if (!c || typeof id !== 'string') return;
  const j = jourParis(date);
  if (!j) return;
  const d = ecart(j, c.inscription);
  if (d < 0 || d > E.evenements_jusqu_a || d > c.age) return;
  const l = reussites.get(artisanId) || [];
  l.push({ t: Date.parse(date), ordre, variante, evenement: { table, id, colonne, date } });
