}
const candidats = [];
let silencieux = 0;
for (const c of dansLaFenetre) {
  const l = reussites.get(c.artisan_id);
  if (!l || !l.length) { silencieux += 1; continue; }
  l.sort((a, b) => a.t - b.t || a.ordre - b.ordre || (a.evenement.id < b.evenement.id ? -1 : a.evenement.id > b.evenement.id ? 1 : 0));
