  candidats.push({ cle: 'suivi:' + c.artisan_id + ':premiers_pas', artisan_id: c.artisan_id, etape: 'premiers_pas', variante: premiere.variante,
    champs: {}, evenements: [premiere.evenement], reste: E.au - c.age, inscription: c.inscription });
}
const s = Object.assign({}, etat.silencieux);
s.premiers_pas = silencieux;
return [{ json: { comptes: etat.comptes, ecartes: etat.ecartes, candidats: etat.candidats.concat(candidats), silencieux: s } }];

// Étape bilan_j14 : les comptes réels depuis l'inscription (demandes reçues, devis envoyés, devis acceptés, factures émises). Une demande
