  if (!t || t.statut !== 'brouillon') throw new Error('texte absent ou non brouillon : ' + b.etape + '.' + b.variante);
  const attendus = (t.objet + '\n' + t.corps).match(/\{[a-z_]+\}/g) || [];
  for (const a of attendus) if (!Object.prototype.hasOwnProperty.call(b.champs, a.slice(1, -1))) throw new Error('champ manquant ' + a + ' pour ' + b.cle);
}
return [{ json: { brouillons: etat.brouillons, reportes: etat.reportes, ecartes: etat.ecartes, silencieux: etat.silencieux, textes: TEXTES } }];

// Brouillons et bilan : la seule sortie. Les brouillons (identifiants, étape, variante, comptes, événements : jamais un nom, une adresse,
// un e-mail ni un texte) et un bilan agrégé par étape. Rien n'est envoyé, rien n'est écrit : l'envoi viendra après la validation des textes.
const R = $('Réglages du suivi').first().json;
