  if (!t || t.statut !== 'brouillon') throw new Error('texte absent ou non brouillon : ' + b.etape + '.' + b.variante);
  const attendus = (t.objet + '\n' + t.corps).match(/\{[a-z_]+\}/g) || [];
  for (const a of attendus) if (!Object.prototype.hasOwnProperty.call(b.champs, a.slice(1, -1))) throw new Error('champ manquant ' + a + ' pour ' + b.cle);
}
return [{ json: { brouillons: etat.brouillons, reportes: etat.reportes, ecartes: etat.ecartes, silencieux: etat.silencieux, textes: TEXTES } }];

// Brouillons et bilan : la seule sortie. Les brouillons (identifiants, étape, variante, comptes, événements : jamais un nom, une adresse,
// un e-mail ni un texte) et un bilan agrégé par étape. Rien n'est envoyé, rien n'est écrit : l'envoi viendra après la validation des textes.
const R = $('Réglages du suivi').first().json;
const etat = $input.first().json;
const par_etape = {};
for (const e of Object.keys(R.etapes)) {
  par_etape[e] = {
    brouillons: etat.brouillons.filter((b) => b.etape === e).length,
    reportes: etat.reportes.filter((b) => b.etape === e).length,
    silencieux: etat.silencieux[e] || 0
  };
}
return [{ json: {
  mode: R.mode,
  mention_ia: R.mention_ia,
  jour: R.jour,
  bilan: { par_etape, ecartes: etat.ecartes, reportes: etat.reportes.map((r) => r.cle) },
  brouillons: etat.brouillons
} }];

// Le passage du matin. L'instant vient du déclencheur (jamais l'horloge du serveur) ; le jour se compte à Paris, comme jourParis
// (lib/comptaTableau.ts:159-160). Seuils : lib/assistant/briefing.ts:35, :37, :38. Limites : lib/assistant/executeurs.ts:164-174
// (200 demandes, paquets de 100, 1 000 messages), :259-264 (50 conversations, 50 impayés, 200 devis), app/api/compta/tableau/route.ts:19
// (2 000 factures). Pages de 1 000 lignes, 50 pages au plus par lecture.
const brut = $('Déclencheur 7 h 30').first().json.timestamp;
const ms = typeof brut === 'string' ? Date.parse(brut) : NaN;
if (!Number.isFinite(ms)) throw new Error('instant du déclencheur illisible');
const instant = new Date(ms);
const jour = new Intl.DateTimeFormat('en-CA', { timeZone: 'Europe/Paris', year: 'numeric', month: '2-digit', day: '2-digit' }).format(instant);
if (!/^\d{4}-\d{2}-\d{2}$/.test(jour)) throw new Error('jour de Paris illisible');
return [{ json: {
  mode: 'simulation',
  instant: instant.toISOString(),
  jour,
  seuils: { devis_sans_reponse_jours: 7, impaye_urgent_jours: 30, lignes_max: 8 },
  limites: { demandes: 200, paquet_demandes: 100, messages_par_paquet: 1000, conversations: 50, impayes_listes: 50, devis: 200, factures: 2000, lignes_par_page: 1000, pages_max: 50 }
} }];

// Copie figée de lib/plans.ts (offres l.66-103, peut() l.149) pour les quatre capacités que lit le point du jour.
// Le juge (scripts/briefing-n8n-qa.mjs) la compare à peut() pour Studio, Signature et Entreprise.
return [{ json: { capacites: {
  studio: { assistant: true, chiffres: true, 'inventaire.stock': true, crm: false },
  signature: { assistant: true, chiffres: true, 'inventaire.stock': true, crm: true },
  entreprise: { assistant: true, chiffres: true, 'inventaire.stock': true, crm: true }
} } }];

// Les comptes lus (Studio, Signature, Entreprise ; ni démonstration, ni suppression demandée), vérifiés ligne par ligne.
// Une lecture qui atteint son plafond de pages, ou une ligne inattendue, arrête le passage : jamais un point du jour tronqué.
const L = $('Contexte du passage').first().json.limites;
const CAP = $('Capacités des offres').first().json.capacites;
const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/;
const lignes = $('Lire comptes').all().map((i) => i.json);
const rangs = lignes.length === 1 && Object.keys(lignes[0] || {}).length === 0 ? [] : lignes;
if (rangs.length >= L.lignes_par_page * L.pages_max) throw new Error('Lire comptes : plafond de pages atteint, lecture incomplète');
const vus = new Map();
for (const a of rangs) {
  if (!a || typeof a !== 'object' || Object.keys(a).sort().join(',') !== 'est_demo,id,plan,suppression_demandee_le') throw new Error('Lire comptes : ligne inattendue');
  if (typeof a.id !== 'string' || !UUID.test(a.id)) throw new Error('Lire comptes : identifiant illisible');
  if (a.est_demo !== false || a.suppression_demandee_le !== null || !Object.prototype.hasOwnProperty.call(CAP, a.plan)) throw new Error('Lire comptes : compte hors du filtre');
  if (vus.has(a.id) && vus.get(a.id) !== a.plan) throw new Error('Lire comptes : compte lu deux fois');
  vus.set(a.id, a.plan);
}
const comptes = [...vus.entries()].map(([id, plan]) => ({ id, plan })).sort((x, y) => (x.id < y.id ? -1 : x.id > y.id ? 1 : 0));
return [{ json: { comptes, ids: comptes.map((c) => c.id).join(',') || '00000000-0000-0000-0000-000000000000' } }];

// Les demandes de chaque compte comme les lit l'assistant (lib/assistant/executeurs.ts:164-166) : les 200 plus récentes par
// updated_at (vides en dernier ; à égalité, par identifiant), puis les ouvertes (ni gagnée ni perdue), par paquets de 100 pour lire
// leurs messages (l.168-174). Une donnée se range par (compte, identifiant).
const L = $('Contexte du passage').first().json.limites;
const comptes = new Set($('Comptes retenus').first().json.comptes.map((c) => c.id));
const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/;
const lignes = $('Lire demandes').all().map((i) => i.json);
const rangs = lignes.length === 1 && Object.keys(lignes[0] || {}).length === 0 ? [] : lignes;
if (rangs.length >= L.lignes_par_page * L.pages_max) throw new Error('Lire demandes : plafond de pages atteint, lecture incomplète');
const cleTemps = (s) => {
  if (typeof s !== 'string') return null;
  const m = /^(.*T\d{2}:\d{2}:\d{2})(?:\.(\d+))?(.*)$/.exec(s);
  const base = Date.parse(m ? m[1] + m[3] : s);
  if (!Number.isFinite(base)) return null;
  return base * 1000 + (m && m[2] ? Number(m[2].padEnd(6, '0').slice(0, 6)) : 0);
};
const ordre = (a, b) => (a < b ? -1 : a > b ? 1 : 0);
const parCompte = new Map();
const vus = new Set();
for (const l of rangs) {
  if (!l || typeof l !== 'object' || Object.keys(l).sort().join(',') !== 'artisan_id,id,lu_le,statut,updated_at,urgence') throw new Error('Lire demandes : ligne inattendue');
  if (typeof l.id !== 'string' || !UUID.test(l.id) || typeof l.artisan_id !== 'string' || !UUID.test(l.artisan_id)) throw new Error('Lire demandes : identifiant illisible');
  if (!comptes.has(l.artisan_id)) continue;
  const cle = l.artisan_id + '|' + l.id;
  if (vus.has(cle)) continue;
  vus.add(cle);
  if (!parCompte.has(l.artisan_id)) parCompte.set(l.artisan_id, []);
  parCompte.get(l.artisan_id).push(l);
}
const paquets = [];
for (const compte of [...parCompte.keys()].sort(ordre)) {
  const triees = parCompte.get(compte).map((l) => ({ l, t: cleTemps(l.updated_at) })).sort((a, b) => {
    if (a.t === null || b.t === null) return a.t === b.t ? ordre(a.l.id, b.l.id) : a.t === null ? 1 : -1;
    return b.t - a.t || ordre(a.l.id, b.l.id);
  }).map((x) => x.l);
  const ouvertes = triees.slice(0, L.demandes).filter((l) => l.statut !== 'gagne' && l.statut !== 'perdu');
  for (let i = 0; i < ouvertes.length; i += L.paquet_demandes) {
    paquets.push({ json: { artisan_id: compte, rang: i / L.paquet_demandes, lead_ids: ouvertes.slice(i, i + L.paquet_demandes).map((l) => l.id).join(',') } });
  }
}
if (!paquets.length) paquets.push({ json: { artisan_id: null, rang: 0, lead_ids: '00000000-0000-0000-0000-000000000000' } });
return paquets;

// Les autres lectures, vérifiées avant tout calcul : colonnes exactes, identifiants lisibles, plafond de pages non atteint.
// Une seule anomalie arrête le passage : jamais un point du jour tronqué, jamais « rien à signaler » sur une source en panne.
// Les messages sont lus par paquets de 100 demandes, 1 000 au plus par paquet, comme l'assistant (lib/assistant/executeurs.ts:168-174).
const L = $('Contexte du passage').first().json.limites;
const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/;
const LECTURES = [
  ['Lire messages', 'etat,lead_id,sens,sent_at', ['lead_id']],
  ['Lire devis envoyés', 'artisan_id,envoye_le,id,statut,total_ttc', ['id', 'artisan_id']],
  ['Lire factures', 'artisan_id,avoir_de,date_echeance,date_emission,id,statut,total_ttc', ['id', 'artisan_id', 'avoir_de']],
  ['Lire matériaux suivis', 'artisan_id,id,seuil_alerte', ['id', 'artisan_id']],
  ['Lire stock', 'id,materiau_id,quantite', ['id', 'materiau_id']],
];
const paquets = $('Paquets de demandes ouvertes').all().length;
const nombres = {};
for (const [nom, colonnes, ids] of LECTURES) {
  const lignes = $(nom).all().map((i) => i.json);
  const rangs = lignes.length === 1 && Object.keys(lignes[0] || {}).length === 0 ? [] : lignes;
  if (nom === 'Lire messages' ? rangs.length > paquets * L.messages_par_paquet : rangs.length >= L.lignes_par_page * L.pages_max) throw new Error(nom + ' : plafond atteint, lecture incomplète');
  for (const r of rangs) {
    if (!r || typeof r !== 'object' || Object.keys(r).sort().join(',') !== colonnes) throw new Error(nom + ' : ligne inattendue');
    for (const k of ids) if (r[k] !== null && (typeof r[k] !== 'string' || !UUID.test(r[k]))) throw new Error(nom + ' : identifiant illisible');
  }
  nombres[nom] = rangs.length;
}
return [{ json: { lectures_completes: true, nombres } }];

// Les conversations qui attendent l'artisan : attenteDe et resumerConversations (lib/assistant/donnees.ts:190-245, en attente
// seulement, 50 au plus), puis le tri de composerBriefing (lib/assistant/briefing.ts:53-55 : les urgentes d'abord, ordre gardé).
// Aucune fenêtre de temps : une demande arrivée la veille à 23 h et jamais lue attend toujours l'artisan.
const L = $('Contexte du passage').first().json.limites;
const comptes = new Set($('Comptes retenus').first().json.comptes.map((c) => c.id));
const demandes = new Map();
for (const i of $('Lire demandes').all()) {
  const l = i.json;
  if (!l || typeof l.id !== 'string' || !comptes.has(l.artisan_id)) continue;
  const cle = l.artisan_id + '|' + l.id;
  if (!demandes.has(cle)) demandes.set(cle, l);
}
const messages = new Map();
for (const i of $('Lire messages').all()) {
  const m = i.json;
  if (!m || typeof m.lead_id !== 'string') continue;
  if (!messages.has(m.lead_id)) messages.set(m.lead_id, []);
  messages.get(m.lead_id).push(m);
}
const attente = (l, siens) => {
  if (l.statut === 'gagne' || l.statut === 'perdu') return null;
  if (siens.some((m) => m.etat === 'proposition')) return 'reponse_a_valider';
  const reels = siens.filter((m) => m.etat == null).sort((a, b) => String(a.sent_at ?? '').localeCompare(String(b.sent_at ?? '')));
  const dernier = reels[reels.length - 1];
  if (dernier && dernier.sens === 'in') return 'client_a_ecrit';
  if (!l.lu_le && (l.statut === 'nouveau' || l.statut === 'en_discussion' || !l.statut)) return 'non_lue';
  return null;
};
const ouvertes = new Map();
for (const p of $('Paquets de demandes ouvertes').all()) {
  const q = p.json;
  if (!q || !comptes.has(q.artisan_id)) continue;
  if (!ouvertes.has(q.artisan_id)) ouvertes.set(q.artisan_id, []);
  for (const id of String(q.lead_ids).split(',')) ouvertes.get(q.artisan_id).push(id);
}
const parCompte = {};
for (const compte of [...ouvertes.keys()].sort()) {
  const enAttente = [];
  for (const id of ouvertes.get(compte)) {
    const l = demandes.get(compte + '|' + id);
    if (!l) throw new Error('demande d’un paquet introuvable');
    if (attente(l, messages.get(id) || [])) enAttente.push(l);
  }
  const triees = enAttente.slice(0, L.conversations).map((l, rang) => ({ l, rang }))
    .sort((a, b) => Number(b.l.urgence === 'urgent') - Number(a.l.urgence === 'urgent') || a.rang - b.rang).map((x) => x.l);
  parCompte[compte] = { nb_en_attente: enAttente.length, liste: triees.map((l) => l.id), urgentes: triees.filter((l) => l.urgence === 'urgent').map((l) => l.id) };
}
return [{ json: { parCompte } }];

// Les devis envoyés sans réponse : la lecture de briefing_du_matin (lib/assistant/executeurs.ts:264 : statut envoyé, envoye_le
// croissant, vides en dernier, 200 au plus ; à égalité, par identifiant), le jour d'envoi compté à Paris (l.277), puis
// composerBriefing (lib/assistant/briefing.ts:40, :58-61 : 7 jours ou plus, le plus ancien d'abord, ordre gardé à égalité).
const C = $('Contexte du passage').first().json;
const comptes = new Set($('Comptes retenus').first().json.comptes.map((c) => c.id));
const format = new Intl.DateTimeFormat('en-CA', { timeZone: 'Europe/Paris', year: 'numeric', month: '2-digit', day: '2-digit' });
const joursEntre = (de, a) => Math.floor((Date.parse(a + 'T00:00:00Z') - Date.parse(de.slice(0, 10) + 'T00:00:00Z')) / 86400000);
const cleTemps = (s) => {
  if (typeof s !== 'string') return null;
  const m = /^(.*T\d{2}:\d{2}:\d{2})(?:\.(\d+))?(.*)$/.exec(s);
  const base = Date.parse(m ? m[1] + m[3] : s);
  if (!Number.isFinite(base)) return null;
  return base * 1000 + (m && m[2] ? Number(m[2].padEnd(6, '0').slice(0, 6)) : 0);
};
const ordre = (a, b) => (a < b ? -1 : a > b ? 1 : 0);
const parCompteLu = new Map();
const vus = new Set();
for (const i of $('Lire devis envoyés').all()) {
  const d = i.json;
  if (!d || typeof d.id !== 'string' || !comptes.has(d.artisan_id) || d.statut !== 'envoye') continue;
  const cle = d.artisan_id + '|' + d.id;
  if (vus.has(cle)) continue;
  vus.add(cle);
  if (!parCompteLu.has(d.artisan_id)) parCompteLu.set(d.artisan_id, []);
  parCompteLu.get(d.artisan_id).push(d);
}
const parCompte = {};
for (const compte of [...parCompteLu.keys()].sort(ordre)) {
  const lus = parCompteLu.get(compte).map((d) => ({ d, t: cleTemps(d.envoye_le) })).sort((a, b) => {
    if (a.t === null || b.t === null) return a.t === b.t ? ordre(a.d.id, b.d.id) : a.t === null ? 1 : -1;
    return a.t - b.t || ordre(a.d.id, b.d.id);
  }).map((x) => x.d).slice(0, C.limites.devis);
  const retenus = lus.map((d, rang) => ({ id: d.id, rang, jours: d.envoye_le ? joursEntre(format.format(new Date(d.envoye_le)), C.jour) : null }))
    .filter((x) => x.jours !== null && x.jours >= C.seuils.devis_sans_reponse_jours)
    .sort((a, b) => b.jours - a.jours || a.rang - b.rang);
  parCompte[compte] = { liste: retenus.map((x) => x.id) };
}
return [{ json: { parCompte } }];

// Les impayés de « Mes chiffres » : la lecture de la route (app/api/compta/tableau/route.ts:19, :37 : 2 000 factures au plus, date
// d'émission décroissante, vides d'abord, puis identifiant), le calcul de l'écran (lib/comptaTableau.ts:211-215 factures comptées,
// :316-337 impayés et leur tri, jours à Paris l.159-169), la liste de resumerFactures (lib/assistant/donnees.ts:111-142, 50 au plus),
// puis les échues de composerBriefing (lib/assistant/briefing.ts:65-68 ; urgentes à 30 jours de retard ou plus).
const C = $('Contexte du passage').first().json;
const comptes = new Set($('Comptes retenus').first().json.comptes.map((c) => c.id));
const format = new Intl.DateTimeFormat('en-CA', { timeZone: 'Europe/Paris', year: 'numeric', month: '2-digit', day: '2-digit' });
const jourDe = (v) => {
  if (typeof v !== 'string') return null;
  if (/^\d{4}-\d{2}-\d{2}$/.test(v)) return v;
  const t = Date.parse(v);
  return Number.isNaN(t) ? null : format.format(new Date(t));
};
const ecartJours = (a, b) => Math.round((Date.UTC(+a.slice(0, 4), +a.slice(5, 7) - 1, +a.slice(8, 10)) - Date.UTC(+b.slice(0, 4), +b.slice(5, 7) - 1, +b.slice(8, 10))) / 86400000);
const centimes = (v) => {
  const n = typeof v === 'number' ? v : typeof v === 'string' ? Number(v.replace(',', '.')) : NaN;
  return Number.isFinite(n) ? Math.round(n * 100) : 0;
};
const ordre = (a, b) => (a < b ? -1 : a > b ? 1 : 0);
const parCompteLu = new Map();
const vus = new Set();
for (const i of $('Lire factures').all()) {
  const f = i.json;
  if (!f || typeof f.id !== 'string' || !comptes.has(f.artisan_id)) continue;
  const cle = f.artisan_id + '|' + f.id;
  if (vus.has(cle)) continue;
  vus.add(cle);
  if (!parCompteLu.has(f.artisan_id)) parCompteLu.set(f.artisan_id, []);
  parCompteLu.get(f.artisan_id).push(f);
}
const jour = C.jour;
const parCompte = {};
for (const compte of [...parCompteLu.keys()].sort(ordre)) {
  const lues = parCompteLu.get(compte).slice().sort((a, b) => {
    const x = typeof a.date_emission === 'string' ? a.date_emission : null, y = typeof b.date_emission === 'string' ? b.date_emission : null;
    if (x === null || y === null) return x === y ? ordre(a.id, b.id) : x === null ? -1 : 1;
    return ordre(y, x) || ordre(a.id, b.id);
  }).slice(0, C.limites.factures);
  const annulees = new Set();
  for (const f of lues) if (typeof f.avoir_de === 'string' && f.avoir_de) annulees.add(f.avoir_de);
  const impayes = [];
  for (const f of lues) {
    if (f.avoir_de || annulees.has(f.id) || f.statut !== 'emise') continue;
    const emission = jourDe(f.date_emission) ?? jour;
    const echeance = jourDe(f.date_echeance);
    impayes.push({ id: f.id, cle: 'presti:' + f.id, montant: centimes(f.total_ttc), emission, joursRetard: echeance && echeance < jour ? ecartJours(jour, echeance) : 0 });
  }
  impayes.sort((a, b) => b.joursRetard - a.joursRetard || a.emission.localeCompare(b.emission) || a.cle.localeCompare(b.cle));
  const echues = impayes.slice(0, C.limites.impayes_listes).filter((i) => i.joursRetard > 0);
  parCompte[compte] = {
    nombre: impayes.length,
    total_centimes: impayes.reduce((s, i) => s + i.montant, 0),
    echues: echues.map((i) => i.id),
    urgentes: echues.filter((i) => i.joursRetard >= C.seuils.impaye_urgent_jours).map((i) => i.id),
  };
}
return [{ json: { parCompte } }];

// Le stock sous le seuil : l'alerte de l'écran Inventaire (app/api/inventaire/route.ts:68-75 : seuil > 0, reste = somme des lieux,
// reste ≤ seuil), épuisé si le reste est à zéro ou moins (lib/assistant/briefing.ts:71). L'écran range par nom (l.63), que ce
// passage ne lit pas : ici, par identifiant (écart déclaré au brief ; le juge compare cette rubrique comme un ensemble).
const comptes = new Set($('Comptes retenus').first().json.comptes.map((c) => c.id));
const ordre = (a, b) => (a < b ? -1 : a > b ? 1 : 0);
const materiaux = new Map();
for (const i of $('Lire matériaux suivis').all()) {
  const m = i.json;
  if (!m || typeof m.id !== 'string' || !comptes.has(m.artisan_id)) continue;
  const cle = m.artisan_id + '|' + m.id;
  if (!materiaux.has(cle)) materiaux.set(cle, { compte: m.artisan_id, id: m.id, seuil: Number(m.seuil_alerte), reste: 0 });
}
const parMateriau = new Map();
for (const m of materiaux.values()) {
  if (!parMateriau.has(m.id)) parMateriau.set(m.id, []);
  parMateriau.get(m.id).push(m);
}
const lignes = $('Lire stock').all().map((i) => i.json).filter((s) => s && typeof s.materiau_id === 'string').sort((a, b) => ordre(a.id, b.id));
for (const s of lignes) for (const m of parMateriau.get(s.materiau_id) || []) m.reste += Number(s.quantite);
const parCompte = {};
for (const m of [...materiaux.values()].sort((a, b) => ordre(a.compte, b.compte) || ordre(a.id, b.id))) {
  if (!(m.seuil > 0 && m.reste <= m.seuil)) continue;
  const e = parCompte[m.compte] || (parCompte[m.compte] = { liste: [], epuises: [] });
  e.liste.push(m.id);
  if (Number.isFinite(m.reste) && m.reste <= 0) e.epuises.push(m.id);
}
return [{ json: { parCompte } }];

// Le point du jour de chaque compte : les rubriques dans l'ordre de composerBriefing (lib/assistant/briefing.ts:52-72), 8 objets
// montrés au plus, les urgences et les chiffres, puis les trois priorités (défaut de la question Q1 : l'argent qui dort d'abord,
// P3:584 ; puis les clients qui attendent ; puis le reste dans l'ordre de composerBriefing). Un compte sans rubrique se tait.
// Simulation : ces lignes seront écrites dans la table de la voie (a) après sa migration ; rien ne s'écrit ni ne part d'ici.
const C = $('Contexte du passage').first().json;
const CAP = $('Capacités des offres').first().json.capacites;
const comptes = $('Comptes retenus').first().json.comptes;
const R = {
  conversations: $('Conversations qui attendent').first().json.parCompte,
  devis: $('Devis sans réponse').first().json.parCompte,
  impayes: $('Impayés').first().json.parCompte,
  stock: $('Stock sous le seuil').first().json.parCompte,
};
const MAX = C.seuils.lignes_max;
const ORDRE_PRIORITES = ['impayes', 'conversations', 'devis_sans_reponse', 'stock_bas'];
const HORS_N8N = ['chantiers_du_jour', 'chantiers_en_retard', 'a_facturer'];
const aEcrire = [];
let horsOffre = 0, muets = 0, muetsCrm = 0;
for (const { id, plan } of comptes) {
  const cap = CAP[plan];
  if (!cap || cap.assistant !== true) { horsOffre++; continue; }
  const conv = R.conversations[id] || { nb_en_attente: 0, liste: [], urgentes: [] };
  const dv = R.devis[id] || { liste: [] };
  const im = cap.chiffres === true ? (R.impayes[id] || { nombre: 0, total_centimes: 0, echues: [], urgentes: [] }) : null;
  const st = cap['inventaire.stock'] === true ? (R.stock[id] || { liste: [], epuises: [] }) : null;
  const rubriques = [];
  const ajouter = (rubrique, objets) => {
    if (objets.length) rubriques.push({ rubrique, nombre: objets.length, lignes_non_montrees: Math.max(0, objets.length - MAX), objets: objets.slice(0, MAX) });
  };
  ajouter('conversations', conv.liste);
  ajouter('devis_sans_reponse', dv.liste);
  if (im) ajouter('impayes', im.echues);
  if (st) ajouter('stock_bas', st.liste);
  const horsN8n = cap.crm === true ? HORS_N8N.slice() : [];
  if (!rubriques.length) { muets++; if (horsN8n.length) muetsCrm++; continue; }
  const urgences = [
    ...conv.urgentes.map((x) => ({ rubrique: 'conversations', id: x })),
    ...(im ? im.urgentes.map((x) => ({ rubrique: 'impayes', id: x })) : []),
    ...(st ? st.epuises.map((x) => ({ rubrique: 'stock_bas', id: x })) : []),
  ];
  const priorites = ORDRE_PRIORITES.map((r) => rubriques.find((x) => x.rubrique === r)).filter(Boolean).slice(0, 3)
    .map((x, i) => ({ rang: i + 1, rubrique: x.rubrique, nombre: x.nombre, premier_objet: x.objets[0] }));
  aEcrire.push({
    cle: 'point_du_jour:' + id + ':' + C.jour,
    artisan_id: id,
    jour: C.jour,
    mode: C.mode,
    priorites,
    point_du_jour: {
      rubriques,
      urgences: { nombre: urgences.length, objets: urgences.slice(0, MAX) },
      chiffres: {
        conversations_en_attente: conv.nb_en_attente,
        devis_sans_reponse: dv.liste.length,
        factures_impayees: im ? im.nombre : null,
        factures_echues: im ? im.echues.length : null,
        total_impaye_centimes: im ? im.total_centimes : null,
        alertes_de_stock: st ? st.liste.length : null,
      },
      rubriques_hors_n8n: horsN8n,
      rubriques_hors_offre: [im ? null : 'impayes', st ? null : 'stock_bas'].filter(Boolean),
    },
  });
}
return [{ json: { mode: C.mode, jour: C.jour, comptes_lus: comptes.length, comptes_hors_offre: horsOffre, comptes_muets: muets, comptes_muets_crm: muetsCrm, a_ecrire: aEcrire } }];

// La seule sortie du passage : un bilan agrégé, sans aucun identifiant de compte. Les lignes « à écrire » restent dans le nœud
// précédent, en simulation, jusqu'à la table de la voie (a) (migration et « go » de Benj).
const P = $('Point du jour par compte').first().json;
const par = { impayes: 0, conversations: 0, devis_sans_reponse: 0, stock_bas: 0 };
for (const l of P.a_ecrire) for (const p of l.priorites) {
  if (!Object.prototype.hasOwnProperty.call(par, p.rubrique)) throw new Error('rubrique de priorité inconnue');
  par[p.rubrique] += 1;
}
return [{ json: {
  mode: P.mode,
  jour: P.jour,
  comptes_lus: P.comptes_lus,
  comptes_avec_point_du_jour: P.a_ecrire.length,
  comptes_muets: P.comptes_muets,
  comptes_muets_rubriques_hors_n8n: P.comptes_muets_crm,
  comptes_hors_offre: P.comptes_hors_offre,
  priorites_par_rubrique: par,
} }];

// Le passage du matin. L'instant vient du déclencheur (jamais l'horloge du serveur) ; le jour se compte à Paris, comme jourParis
// (lib/comptaTableau.ts:159-160). Seuils : lib/assistant/briefing.ts:35, :37, :38. Limites : lib/assistant/executeurs.ts:164-174
// (200 demandes, paquets de 100, 1 000 messages), :259-264 (50 conversations, 50 impayés, 200 devis), app/api/compta/tableau/route.ts:19
// (2 000 factures). Pages de 1 000 lignes, 50 pages au plus par lecture.
const brut = $('Déclencheur 7 h 30').first().json.timestamp;
const ms = typeof brut === 'string' ? Date.parse(brut) : NaN;
if (!Number.isFinite(ms)) throw new Error('instant du déclencheur illisible');
const instant = new Date(ms);
const jour = new Intl.DateTimeFormat('en-CA', { timeZone: 'Europe/Paris', year: 'numeric', month: '2-digit', day: '2-digit' }).format(instant);
if (!/^\d{4}-\d{2}-\d{2}$/.test(jour)) throw new Error('jour de Paris illisible');
return [{ json: {
  mode: 'simulation',
  instant: instant.toISOString(),
  jour,
  seuils: { devis_sans_reponse_jours: 7, impaye_urgent_jours: 30, lignes_max: 8 },
  limites: { demandes: 200, paquet_demandes: 100, messages_par_paquet: 1000, conversations: 50, impayes_listes: 50, devis: 200, factures: 2000, lignes_par_page: 1000, pages_max: 50 }
} }];

// Copie figée de lib/plans.ts (offres l.66-103, peut() l.149) pour les quatre capacités que lit le point du jour.
// Le juge (scripts/briefing-n8n-qa.mjs) la compare à peut() pour Studio, Signature et Entreprise.
return [{ json: { capacites: {
  studio: { assistant: true, chiffres: true, 'inventaire.stock': true, crm: false },
  signature: { assistant: true, chiffres: true, 'inventaire.stock': true, crm: true },
  entreprise: { assistant: true, chiffres: true, 'inventaire.stock': true, crm: true }
} } }];

// Les comptes lus (Studio, Signature, Entreprise ; ni démonstration, ni suppression demandée), vérifiés ligne par ligne.
// Une lecture qui atteint son plafond de pages, ou une ligne inattendue, arrête le passage : jamais un point du jour tronqué.
const L = $('Contexte du passage').first().json.limites;
const CAP = $('Capacités des offres').first().json.capacites;
const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/;
const lignes = $('Lire comptes').all().map((i) => i.json);
const rangs = lignes.length === 1 && Object.keys(lignes[0] || {}).length === 0 ? [] : lignes;
if (rangs.length >= L.lignes_par_page * L.pages_max) throw new Error('Lire comptes : plafond de pages atteint, lecture incomplète');
const vus = new Map();
for (const a of rangs) {
  if (!a || typeof a !== 'object' || Object.keys(a).sort().join(',') !== 'est_demo,id,plan,suppression_demandee_le') throw new Error('Lire comptes : ligne inattendue');
  if (typeof a.id !== 'string' || !UUID.test(a.id)) throw new Error('Lire comptes : identifiant illisible');
  if (a.est_demo !== false || a.suppression_demandee_le !== null || !Object.prototype.hasOwnProperty.call(CAP, a.plan)) throw new Error('Lire comptes : compte hors du filtre');
  if (vus.has(a.id) && vus.get(a.id) !== a.plan) throw new Error('Lire comptes : compte lu deux fois');
  vus.set(a.id, a.plan);
}
const comptes = [...vus.entries()].map(([id, plan]) => ({ id, plan })).sort((x, y) => (x.id < y.id ? -1 : x.id > y.id ? 1 : 0));
return [{ json: { comptes, ids: comptes.map((c) => c.id).join(',') || '00000000-0000-0000-0000-000000000000' } }];

// Les demandes de chaque compte comme les lit l'assistant (lib/assistant/executeurs.ts:164-166) : les 200 plus récentes par
// updated_at (vides en dernier ; à égalité, par identifiant), puis les ouvertes (ni gagnée ni perdue), par paquets de 100 pour lire
// leurs messages (l.168-174). Une donnée se range par (compte, identifiant).
const L = $('Contexte du passage').first().json.limites;
const comptes = new Set($('Comptes retenus').first().json.comptes.map((c) => c.id));
const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/;
const lignes = $('Lire demandes').all().map((i) => i.json);
const rangs = lignes.length === 1 && Object.keys(lignes[0] || {}).length === 0 ? [] : lignes;
if (rangs.length >= L.lignes_par_page * L.pages_max) throw new Error('Lire demandes : plafond de pages atteint, lecture incomplète');
const cleTemps = (s) => {
  if (typeof s !== 'string') return null;
  const m = /^(.*T\d{2}:\d{2}:\d{2})(?:\.(\d+))?(.*)$/.exec(s);
  const base = Date.parse(m ? m[1] + m[3] : s);
  if (!Number.isFinite(base)) return null;
  return base * 1000 + (m && m[2] ? Number(m[2].padEnd(6, '0').slice(0, 6)) : 0);
};
const ordre = (a, b) => (a < b ? -1 : a > b ? 1 : 0);
const parCompte = new Map();
const vus = new Set();
for (const l of rangs) {
  if (!l || typeof l !== 'object' || Object.keys(l).sort().join(',') !== 'artisan_id,id,lu_le,statut,updated_at,urgence') throw new Error('Lire demandes : ligne inattendue');
  if (typeof l.id !== 'string' || !UUID.test(l.id) || typeof l.artisan_id !== 'string' || !UUID.test(l.artisan_id)) throw new Error('Lire demandes : identifiant illisible');
  if (!comptes.has(l.artisan_id)) continue;
  const cle = l.artisan_id + '|' + l.id;
  if (vus.has(cle)) continue;
  vus.add(cle);
  if (!parCompte.has(l.artisan_id)) parCompte.set(l.artisan_id, []);
  parCompte.get(l.artisan_id).push(l);
}
const paquets = [];
for (const compte of [...parCompte.keys()].sort(ordre)) {
  const triees = parCompte.get(compte).map((l) => ({ l, t: cleTemps(l.updated_at) })).sort((a, b) => {
    if (a.t === null || b.t === null) return a.t === b.t ? ordre(a.l.id, b.l.id) : a.t === null ? 1 : -1;
    return b.t - a.t || ordre(a.l.id, b.l.id);
  }).map((x) => x.l);
  const ouvertes = triees.slice(0, L.demandes).filter((l) => l.statut !== 'gagne' && l.statut !== 'perdu');
  for (let i = 0; i < ouvertes.length; i += L.paquet_demandes) {
    paquets.push({ json: { artisan_id: compte, rang: i / L.paquet_demandes, lead_ids: ouvertes.slice(i, i + L.paquet_demandes).map((l) => l.id).join(',') } });
  }
}
if (!paquets.length) paquets.push({ json: { artisan_id: null, rang: 0, lead_ids: '00000000-0000-0000-0000-000000000000' } });
return paquets;

// Les autres lectures, vérifiées avant tout calcul : colonnes exactes, identifiants lisibles, plafond de pages non atteint.
// Une seule anomalie arrête le passage : jamais un point du jour tronqué, jamais « rien à signaler » sur une source en panne.
// Les messages sont lus par paquets de 100 demandes, 1 000 au plus par paquet, comme l'assistant (lib/assistant/executeurs.ts:168-174).
const L = $('Contexte du passage').first().json.limites;
const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/;
const LECTURES = [
  ['Lire messages', 'etat,lead_id,sens,sent_at', ['lead_id']],
  ['Lire devis envoyés', 'artisan_id,envoye_le,id,statut,total_ttc', ['id', 'artisan_id']],
  ['Lire factures', 'artisan_id,avoir_de,date_echeance,date_emission,id,statut,total_ttc', ['id', 'artisan_id', 'avoir_de']],
  ['Lire matériaux suivis', 'artisan_id,id,seuil_alerte', ['id', 'artisan_id']],
  ['Lire stock', 'id,materiau_id,quantite', ['id', 'materiau_id']],
];
const paquets = $('Paquets de demandes ouvertes').all().length;
const nombres = {};
for (const [nom, colonnes, ids] of LECTURES) {
  const lignes = $(nom).all().map((i) => i.json);
  const rangs = lignes.length === 1 && Object.keys(lignes[0] || {}).length === 0 ? [] : lignes;
  if (nom === 'Lire messages' ? rangs.length > paquets * L.messages_par_paquet : rangs.length >= L.lignes_par_page * L.pages_max) throw new Error(nom + ' : plafond atteint, lecture incomplète');
  for (const r of rangs) {
    if (!r || typeof r !== 'object' || Object.keys(r).sort().join(',') !== colonnes) throw new Error(nom + ' : ligne inattendue');
    for (const k of ids) if (r[k] !== null && (typeof r[k] !== 'string' || !UUID.test(r[k]))) throw new Error(nom + ' : identifiant illisible');
  }
  nombres[nom] = rangs.length;
}
return [{ json: { lectures_completes: true, nombres } }];

// Les conversations qui attendent l'artisan : attenteDe et resumerConversations (lib/assistant/donnees.ts:190-245, en attente
// seulement, 50 au plus), puis le tri de composerBriefing (lib/assistant/briefing.ts:53-55 : les urgentes d'abord, ordre gardé).
// Aucune fenêtre de temps : une demande arrivée la veille à 23 h et jamais lue attend toujours l'artisan.
const L = $('Contexte du passage').first().json.limites;
const comptes = new Set($('Comptes retenus').first().json.comptes.map((c) => c.id));
const demandes = new Map();
for (const i of $('Lire demandes').all()) {
  const l = i.json;
  if (!l || typeof l.id !== 'string' || !comptes.has(l.artisan_id)) continue;
  const cle = l.artisan_id + '|' + l.id;
  if (!demandes.has(cle)) demandes.set(cle, l);
}
const messages = new Map();
for (const i of $('Lire messages').all()) {
  const m = i.json;
  if (!m || typeof m.lead_id !== 'string') continue;
  if (!messages.has(m.lead_id)) messages.set(m.lead_id, []);
  messages.get(m.lead_id).push(m);
}
const attente = (l, siens) => {
  if (l.statut === 'gagne' || l.statut === 'perdu') return null;
  if (siens.some((m) => m.etat === 'proposition')) return 'reponse_a_valider';
  const reels = siens.filter((m) => m.etat == null).sort((a, b) => String(a.sent_at ?? '').localeCompare(String(b.sent_at ?? '')));
  const dernier = reels[reels.length - 1];
  if (dernier && dernier.sens === 'in') return 'client_a_ecrit';
  if (!l.lu_le && (l.statut === 'nouveau' || l.statut === 'en_discussion' || !l.statut)) return 'non_lue';
  return null;
};
const ouvertes = new Map();
for (const p of $('Paquets de demandes ouvertes').all()) {
  const q = p.json;
  if (!q || !comptes.has(q.artisan_id)) continue;
  if (!ouvertes.has(q.artisan_id)) ouvertes.set(q.artisan_id, []);
  for (const id of String(q.lead_ids).split(',')) ouvertes.get(q.artisan_id).push(id);
}
const parCompte = {};
for (const compte of [...ouvertes.keys()].sort()) {
  const enAttente = [];
  for (const id of ouvertes.get(compte)) {
    const l = demandes.get(compte + '|' + id);
    if (!l) throw new Error('demande d’un paquet introuvable');
    if (attente(l, messages.get(id) || [])) enAttente.push(l);
  }
  const triees = enAttente.slice(0, L.conversations).map((l, rang) => ({ l, rang }))
    .sort((a, b) => Number(b.l.urgence === 'urgent') - Number(a.l.urgence === 'urgent') || a.rang - b.rang).map((x) => x.l);
  parCompte[compte] = { nb_en_attente: enAttente.length, liste: triees.map((l) => l.id), urgentes: triees.filter((l) => l.urgence === 'urgent').map((l) => l.id) };
}
return [{ json: { parCompte } }];

// Les devis envoyés sans réponse : la lecture de briefing_du_matin (lib/assistant/executeurs.ts:264 : statut envoyé, envoye_le
// croissant, vides en dernier, 200 au plus ; à égalité, par identifiant), le jour d'envoi compté à Paris (l.277), puis
// composerBriefing (lib/assistant/briefing.ts:40, :58-61 : 7 jours ou plus, le plus ancien d'abord, ordre gardé à égalité).
const C = $('Contexte du passage').first().json;
const comptes = new Set($('Comptes retenus').first().json.comptes.map((c) => c.id));
const format = new Intl.DateTimeFormat('en-CA', { timeZone: 'Europe/Paris', year: 'numeric', month: '2-digit', day: '2-digit' });
const joursEntre = (de, a) => Math.floor((Date.parse(a + 'T00:00:00Z') - Date.parse(de.slice(0, 10) + 'T00:00:00Z')) / 86400000);
const cleTemps = (s) => {
  if (typeof s !== 'string') return null;
  const m = /^(.*T\d{2}:\d{2}:\d{2})(?:\.(\d+))?(.*)$/.exec(s);
  const base = Date.parse(m ? m[1] + m[3] : s);
  if (!Number.isFinite(base)) return null;
  return base * 1000 + (m && m[2] ? Number(m[2].padEnd(6, '0').slice(0, 6)) : 0);
};
const ordre = (a, b) => (a < b ? -1 : a > b ? 1 : 0);
const parCompteLu = new Map();
const vus = new Set();
for (const i of $('Lire devis envoyés').all()) {
  const d = i.json;
  if (!d || typeof d.id !== 'string' || !comptes.has(d.artisan_id) || d.statut !== 'envoye') continue;
  const cle = d.artisan_id + '|' + d.id;
  if (vus.has(cle)) continue;
  vus.add(cle);
  if (!parCompteLu.has(d.artisan_id)) parCompteLu.set(d.artisan_id, []);
  parCompteLu.get(d.artisan_id).push(d);
}
const parCompte = {};
for (const compte of [...parCompteLu.keys()].sort(ordre)) {
  const lus = parCompteLu.get(compte).map((d) => ({ d, t: cleTemps(d.envoye_le) })).sort((a, b) => {
    if (a.t === null || b.t === null) return a.t === b.t ? ordre(a.d.id, b.d.id) : a.t === null ? 1 : -1;
    return a.t - b.t || ordre(a.d.id, b.d.id);
  }).map((x) => x.d).slice(0, C.limites.devis);
  const retenus = lus.map((d, rang) => ({ id: d.id, rang, jours: d.envoye_le ? joursEntre(format.format(new Date(d.envoye_le)), C.jour) : null }))
    .filter((x) => x.jours !== null && x.jours >= C.seuils.devis_sans_reponse_jours)
    .sort((a, b) => b.jours - a.jours || a.rang - b.rang);
  parCompte[compte] = { liste: retenus.map((x) => x.id) };
}
return [{ json: { parCompte } }];

// Les impayés de « Mes chiffres » : la lecture de la route (app/api/compta/tableau/route.ts:19, :37 : 2 000 factures au plus, date
// d'émission décroissante, vides d'abord, puis identifiant), le calcul de l'écran (lib/comptaTableau.ts:211-215 factures comptées,
// :316-337 impayés et leur tri, jours à Paris l.159-169), la liste de resumerFactures (lib/assistant/donnees.ts:111-142, 50 au plus),
// puis les échues de composerBriefing (lib/assistant/briefing.ts:65-68 ; urgentes à 30 jours de retard ou plus).
const C = $('Contexte du passage').first().json;
const comptes = new Set($('Comptes retenus').first().json.comptes.map((c) => c.id));
const format = new Intl.DateTimeFormat('en-CA', { timeZone: 'Europe/Paris', year: 'numeric', month: '2-digit', day: '2-digit' });
const jourDe = (v) => {
  if (typeof v !== 'string') return null;
  if (/^\d{4}-\d{2}-\d{2}$/.test(v)) return v;
  const t = Date.parse(v);
  return Number.isNaN(t) ? null : format.format(new Date(t));
};
const ecartJours = (a, b) => Math.round((Date.UTC(+a.slice(0, 4), +a.slice(5, 7) - 1, +a.slice(8, 10)) - Date.UTC(+b.slice(0, 4), +b.slice(5, 7) - 1, +b.slice(8, 10))) / 86400000);
const centimes = (v) => {
  const n = typeof v === 'number' ? v : typeof v === 'string' ? Number(v.replace(',', '.')) : NaN;
  return Number.isFinite(n) ? Math.round(n * 100) : 0;
};
const ordre = (a, b) => (a < b ? -1 : a > b ? 1 : 0);
const parCompteLu = new Map();
const vus = new Set();
for (const i of $('Lire factures').all()) {
  const f = i.json;
  if (!f || typeof f.id !== 'string' || !comptes.has(f.artisan_id)) continue;
  const cle = f.artisan_id + '|' + f.id;
  if (vus.has(cle)) continue;
  vus.add(cle);
  if (!parCompteLu.has(f.artisan_id)) parCompteLu.set(f.artisan_id, []);
  parCompteLu.get(f.artisan_id).push(f);
}
const jour = C.jour;
const parCompte = {};
for (const compte of [...parCompteLu.keys()].sort(ordre)) {
  const lues = parCompteLu.get(compte).slice().sort((a, b) => {
    const x = typeof a.date_emission === 'string' ? a.date_emission : null, y = typeof b.date_emission === 'string' ? b.date_emission : null;
    if (x === null || y === null) return x === y ? ordre(a.id, b.id) : x === null ? -1 : 1;
    return ordre(y, x) || ordre(a.id, b.id);
  }).slice(0, C.limites.factures);
  const annulees = new Set();
  for (const f of lues) if (typeof f.avoir_de === 'string' && f.avoir_de) annulees.add(f.avoir_de);
  const impayes = [];
  for (const f of lues) {
    if (f.avoir_de || annulees.has(f.id) || f.statut !== 'emise') continue;
    const emission = jourDe(f.date_emission) ?? jour;
    const echeance = jourDe(f.date_echeance);
    impayes.push({ id: f.id, cle: 'presti:' + f.id, montant: centimes(f.total_ttc), emission, joursRetard: echeance && echeance < jour ? ecartJours(jour, echeance) : 0 });
  }
  impayes.sort((a, b) => b.joursRetard - a.joursRetard || a.emission.localeCompare(b.emission) || a.cle.localeCompare(b.cle));
  const echues = impayes.slice(0, C.limites.impayes_listes).filter((i) => i.joursRetard > 0);
  parCompte[compte] = {
    nombre: impayes.length,
    total_centimes: impayes.reduce((s, i) => s + i.montant, 0),
    echues: echues.map((i) => i.id),
    urgentes: echues.filter((i) => i.joursRetard >= C.seuils.impaye_urgent_jours).map((i) => i.id),
  };
}
return [{ json: { parCompte } }];

// Le stock sous le seuil : l'alerte de l'écran Inventaire (app/api/inventaire/route.ts:68-75 : seuil > 0, reste = somme des lieux,
// reste ≤ seuil), épuisé si le reste est à zéro ou moins (lib/assistant/briefing.ts:71). L'écran range par nom (l.63), que ce
// passage ne lit pas : ici, par identifiant (écart déclaré au brief ; le juge compare cette rubrique comme un ensemble).
const comptes = new Set($('Comptes retenus').first().json.comptes.map((c) => c.id));
const ordre = (a, b) => (a < b ? -1 : a > b ? 1 : 0);
const materiaux = new Map();
for (const i of $('Lire matériaux suivis').all()) {
  const m = i.json;
  if (!m || typeof m.id !== 'string' || !comptes.has(m.artisan_id)) continue;
  const cle = m.artisan_id + '|' + m.id;
  if (!materiaux.has(cle)) materiaux.set(cle, { compte: m.artisan_id, id: m.id, seuil: Number(m.seuil_alerte), reste: 0 });
}
const parMateriau = new Map();
for (const m of materiaux.values()) {
  if (!parMateriau.has(m.id)) parMateriau.set(m.id, []);
  parMateriau.get(m.id).push(m);
}
const lignes = $('Lire stock').all().map((i) => i.json).filter((s) => s && typeof s.materiau_id === 'string').sort((a, b) => ordre(a.id, b.id));
for (const s of lignes) for (const m of parMateriau.get(s.materiau_id) || []) m.reste += Number(s.quantite);
const parCompte = {};
for (const m of [...materiaux.values()].sort((a, b) => ordre(a.compte, b.compte) || ordre(a.id, b.id))) {
  if (!(m.seuil > 0 && m.reste <= m.seuil)) continue;
  const e = parCompte[m.compte] || (parCompte[m.compte] = { liste: [], epuises: [] });
  e.liste.push(m.id);
  if (Number.isFinite(m.reste) && m.reste <= 0) e.epuises.push(m.id);
}
return [{ json: { parCompte } }];

// Le point du jour de chaque compte : les rubriques dans l'ordre de composerBriefing (lib/assistant/briefing.ts:52-72), 8 objets
// montrés au plus, les urgences et les chiffres, puis les trois priorités (défaut de la question Q1 : l'argent qui dort d'abord,
// P3:584 ; puis les clients qui attendent ; puis le reste dans l'ordre de composerBriefing). Un compte sans rubrique se tait.
// Simulation : ces lignes seront écrites dans la table de la voie (a) après sa migration ; rien ne s'écrit ni ne part d'ici.
const C = $('Contexte du passage').first().json;
const CAP = $('Capacités des offres').first().json.capacites;
const comptes = $('Comptes retenus').first().json.comptes;
const R = {
  conversations: $('Conversations qui attendent').first().json.parCompte,
  devis: $('Devis sans réponse').first().json.parCompte,
  impayes: $('Impayés').first().json.parCompte,
  stock: $('Stock sous le seuil').first().json.parCompte,
};
const MAX = C.seuils.lignes_max;
const ORDRE_PRIORITES = ['impayes', 'conversations', 'devis_sans_reponse', 'stock_bas'];
const HORS_N8N = ['chantiers_du_jour', 'chantiers_en_retard', 'a_facturer'];
const aEcrire = [];
let horsOffre = 0, muets = 0, muetsCrm = 0;
for (const { id, plan } of comptes) {
  const cap = CAP[plan];
  if (!cap || cap.assistant !== true) { horsOffre++; continue; }
  const conv = R.conversations[id] || { nb_en_attente: 0, liste: [], urgentes: [] };
  const dv = R.devis[id] || { liste: [] };
  const im = cap.chiffres === true ? (R.impayes[id] || { nombre: 0, total_centimes: 0, echues: [], urgentes: [] }) : null;
  const st = cap['inventaire.stock'] === true ? (R.stock[id] || { liste: [], epuises: [] }) : null;
  const rubriques = [];
  const ajouter = (rubrique, objets) => {
    if (objets.length) rubriques.push({ rubrique, nombre: objets.length, lignes_non_montrees: Math.max(0, objets.length - MAX), objets: objets.slice(0, MAX) });
  };
  ajouter('conversations', conv.liste);
  ajouter('devis_sans_reponse', dv.liste);
  if (im) ajouter('impayes', im.echues);
  if (st) ajouter('stock_bas', st.liste);
  const horsN8n = cap.crm === true ? HORS_N8N.slice() : [];
  if (!rubriques.length) { muets++; if (horsN8n.length) muetsCrm++; continue; }
  const urgences = [
    ...conv.urgentes.map((x) => ({ rubrique: 'conversations', id: x })),
    ...(im ? im.urgentes.map((x) => ({ rubrique: 'impayes', id: x })) : []),
    ...(st ? st.epuises.map((x) => ({ rubrique: 'stock_bas', id: x })) : []),
  ];
  const priorites = ORDRE_PRIORITES.map((r) => rubriques.find((x) => x.rubrique === r)).filter(Boolean).slice(0, 3)
    .map((x, i) => ({ rang: i + 1, rubrique: x.rubrique, nombre: x.nombre, premier_objet: x.objets[0] }));
  aEcrire.push({
    cle: 'point_du_jour:' + id + ':' + C.jour,
    artisan_id: id,
    jour: C.jour,
    mode: C.mode,
    priorites,
    point_du_jour: {
      rubriques,
      urgences: { nombre: urgences.length, objets: urgences.slice(0, MAX) },
      chiffres: {
        conversations_en_attente: conv.nb_en_attente,
        devis_sans_reponse: dv.liste.length,
        factures_impayees: im ? im.nombre : null,
        factures_echues: im ? im.echues.length : null,
        total_impaye_centimes: im ? im.total_centimes : null,
        alertes_de_stock: st ? st.liste.length : null,
      },
      rubriques_hors_n8n: horsN8n,
      rubriques_hors_offre: [im ? null : 'impayes', st ? null : 'stock_bas'].filter(Boolean),
    },
  });
}
return [{ json: { mode: C.mode, jour: C.jour, comptes_lus: comptes.length, comptes_hors_offre: horsOffre, comptes_muets: muets, comptes_muets_crm: muetsCrm, a_ecrire: aEcrire } }];

// La seule sortie du passage : un bilan agrégé, sans aucun identifiant de compte. Les lignes « à écrire » restent dans le nœud
// précédent, en simulation, jusqu'à la table de la voie (a) (migration et « go » de Benj).
const P = $('Point du jour par compte').first().json;
const par = { impayes: 0, conversations: 0, devis_sans_reponse: 0, stock_bas: 0 };
for (const l of P.a_ecrire) for (const p of l.priorites) {
  if (!Object.prototype.hasOwnProperty.call(par, p.rubrique)) throw new Error('rubrique de priorité inconnue');
  par[p.rubrique] += 1;
}
return [{ json: {
  mode: P.mode,
  jour: P.jour,
  comptes_lus: P.comptes_lus,
  comptes_avec_point_du_jour: P.a_ecrire.length,
  comptes_muets: P.comptes_muets,
  comptes_muets_rubriques_hors_n8n: P.comptes_muets_crm,
  comptes_hors_offre: P.comptes_hors_offre,
  priorites_par_rubrique: par,
} }];

// Le passage du matin. L'instant vient du déclencheur (jamais l'horloge du serveur) ; le jour se compte à Paris, comme jourParis
// (lib/comptaTableau.ts:159-160). Seuils : lib/assistant/briefing.ts:35, :37, :38. Limites : lib/assistant/executeurs.ts:164-174
// (200 demandes, paquets de 100, 1 000 messages), :259-264 (50 conversations, 50 impayés, 200 devis), app/api/compta/tableau/route.ts:19
// (2 000 factures). Pages de 1 000 lignes, 50 pages au plus par lecture.
const brut = $('Déclencheur 7 h 30').first().json.timestamp;
const ms = typeof brut === 'string' ? Date.parse(brut) : NaN;
if (!Number.isFinite(ms)) throw new Error('instant du déclencheur illisible');
const instant = new Date(ms);
const jour = new Intl.DateTimeFormat('en-CA', { timeZone: 'Europe/Paris', year: 'numeric', month: '2-digit', day: '2-digit' }).format(instant);
if (!/^\d{4}-\d{2}-\d{2}$/.test(jour)) throw new Error('jour de Paris illisible');
return [{ json: {
  mode: 'simulation',
  instant: instant.toISOString(),
  jour,
  seuils: { devis_sans_reponse_jours: 7, impaye_urgent_jours: 30, lignes_max: 8 },
  limites: { demandes: 200, paquet_demandes: 100, messages_par_paquet: 1000, conversations: 50, impayes_listes: 50, devis: 200, factures: 2000, lignes_par_page: 1000, pages_max: 50 }
} }];

// Copie figée de lib/plans.ts (offres l.66-103, peut() l.149) pour les quatre capacités que lit le point du jour.
// Le juge (scripts/briefing-n8n-qa.mjs) la compare à peut() pour Studio, Signature et Entreprise.
return [{ json: { capacites: {
  studio: { assistant: true, chiffres: true, 'inventaire.stock': true, crm: false },
  signature: { assistant: true, chiffres: true, 'inventaire.stock': true, crm: true },
  entreprise: { assistant: true, chiffres: true, 'inventaire.stock': true, crm: true }
} } }];

// Les comptes lus (Studio, Signature, Entreprise ; ni démonstration, ni suppression demandée), vérifiés ligne par ligne.
// Une lecture qui atteint son plafond de pages, ou une ligne inattendue, arrête le passage : jamais un point du jour tronqué.
const L = $('Contexte du passage').first().json.limites;
const CAP = $('Capacités des offres').first().json.capacites;
const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/;
const lignes = $('Lire comptes').all().map((i) => i.json);
const rangs = lignes.length === 1 && Object.keys(lignes[0] || {}).length === 0 ? [] : lignes;
if (rangs.length >= L.lignes_par_page * L.pages_max) throw new Error('Lire comptes : plafond de pages atteint, lecture incomplète');
const vus = new Map();
for (const a of rangs) {
  if (!a || typeof a !== 'object' || Object.keys(a).sort().join(',') !== 'est_demo,id,plan,suppression_demandee_le') throw new Error('Lire comptes : ligne inattendue');
  if (typeof a.id !== 'string' || !UUID.test(a.id)) throw new Error('Lire comptes : identifiant illisible');
  if (a.est_demo !== false || a.suppression_demandee_le !== null || !Object.prototype.hasOwnProperty.call(CAP, a.plan)) throw new Error('Lire comptes : compte hors du filtre');
  if (vus.has(a.id) && vus.get(a.id) !== a.plan) throw new Error('Lire comptes : compte lu deux fois');
  vus.set(a.id, a.plan);
}
const comptes = [...vus.entries()].map(([id, plan]) => ({ id, plan })).sort((x, y) => (x.id < y.id ? -1 : x.id > y.id ? 1 : 0));
return [{ json: { comptes, ids: comptes.map((c) => c.id).join(',') || '00000000-0000-0000-0000-000000000000' } }];

// Les demandes de chaque compte comme les lit l'assistant (lib/assistant/executeurs.ts:164-166) : les 200 plus récentes par
// updated_at (vides en dernier ; à égalité, par identifiant), puis les ouvertes (ni gagnée ni perdue), par paquets de 100 pour lire
// leurs messages (l.168-174). Une donnée se range par (compte, identifiant).
const L = $('Contexte du passage').first().json.limites;
const comptes = new Set($('Comptes retenus').first().json.comptes.map((c) => c.id));
const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/;
const lignes = $('Lire demandes').all().map((i) => i.json);
const rangs = lignes.length === 1 && Object.keys(lignes[0] || {}).length === 0 ? [] : lignes;
if (rangs.length >= L.lignes_par_page * L.pages_max) throw new Error('Lire demandes : plafond de pages atteint, lecture incomplète');
const cleTemps = (s) => {
  if (typeof s !== 'string') return null;
  const m = /^(.*T\d{2}:\d{2}:\d{2})(?:\.(\d+))?(.*)$/.exec(s);
  const base = Date.parse(m ? m[1] + m[3] : s);
  if (!Number.isFinite(base)) return null;
  return base * 1000 + (m && m[2] ? Number(m[2].padEnd(6, '0').slice(0, 6)) : 0);
};
const ordre = (a, b) => (a < b ? -1 : a > b ? 1 : 0);
const parCompte = new Map();
const vus = new Set();
for (const l of rangs) {
  if (!l || typeof l !== 'object' || Object.keys(l).sort().join(',') !== 'artisan_id,id,lu_le,statut,updated_at,urgence') throw new Error('Lire demandes : ligne inattendue');
  if (typeof l.id !== 'string' || !UUID.test(l.id) || typeof l.artisan_id !== 'string' || !UUID.test(l.artisan_id)) throw new Error('Lire demandes : identifiant illisible');
  if (!comptes.has(l.artisan_id)) continue;
  const cle = l.artisan_id + '|' + l.id;
  if (vus.has(cle)) continue;
  vus.add(cle);
  if (!parCompte.has(l.artisan_id)) parCompte.set(l.artisan_id, []);
  parCompte.get(l.artisan_id).push(l);
}
const paquets = [];
for (const compte of [...parCompte.keys()].sort(ordre)) {
  const triees = parCompte.get(compte).map((l) => ({ l, t: cleTemps(l.updated_at) })).sort((a, b) => {
    if (a.t === null || b.t === null) return a.t === b.t ? ordre(a.l.id, b.l.id) : a.t === null ? 1 : -1;
    return b.t - a.t || ordre(a.l.id, b.l.id);
  }).map((x) => x.l);
  const ouvertes = triees.slice(0, L.demandes).filter((l) => l.statut !== 'gagne' && l.statut !== 'perdu');
  for (let i = 0; i < ouvertes.length; i += L.paquet_demandes) {
    paquets.push({ json: { artisan_id: compte, rang: i / L.paquet_demandes, lead_ids: ouvertes.slice(i, i + L.paquet_demandes).map((l) => l.id).join(',') } });
  }
}
if (!paquets.length) paquets.push({ json: { artisan_id: null, rang: 0, lead_ids: '00000000-0000-0000-0000-000000000000' } });
return paquets;

// Les autres lectures, vérifiées avant tout calcul : colonnes exactes, identifiants lisibles, plafond de pages non atteint.
// Une seule anomalie arrête le passage : jamais un point du jour tronqué, jamais « rien à signaler » sur une source en panne.
// Les messages sont lus par paquets de 100 demandes, 1 000 au plus par paquet, comme l'assistant (lib/assistant/executeurs.ts:168-174).
const L = $('Contexte du passage').first().json.limites;
const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/;
const LECTURES = [
  ['Lire messages', 'etat,lead_id,sens,sent_at', ['lead_id']],
  ['Lire devis envoyés', 'artisan_id,envoye_le,id,statut,total_ttc', ['id', 'artisan_id']],
  ['Lire factures', 'artisan_id,avoir_de,date_echeance,date_emission,id,statut,total_ttc', ['id', 'artisan_id', 'avoir_de']],
  ['Lire matériaux suivis', 'artisan_id,id,seuil_alerte', ['id', 'artisan_id']],
  ['Lire stock', 'id,materiau_id,quantite', ['id', 'materiau_id']],
];
const paquets = $('Paquets de demandes ouvertes').all().length;
const nombres = {};
for (const [nom, colonnes, ids] of LECTURES) {
  const lignes = $(nom).all().map((i) => i.json);
  const rangs = lignes.length === 1 && Object.keys(lignes[0] || {}).length === 0 ? [] : lignes;
  if (nom === 'Lire messages' ? rangs.length > paquets * L.messages_par_paquet : rangs.length >= L.lignes_par_page * L.pages_max) throw new Error(nom + ' : plafond atteint, lecture incomplète');
  for (const r of rangs) {
    if (!r || typeof r !== 'object' || Object.keys(r).sort().join(',') !== colonnes) throw new Error(nom + ' : ligne inattendue');
    for (const k of ids) if (r[k] !== null && (typeof r[k] !== 'string' || !UUID.test(r[k]))) throw new Error(nom + ' : identifiant illisible');
  }
  nombres[nom] = rangs.length;
}
return [{ json: { lectures_completes: true, nombres } }];

// Les conversations qui attendent l'artisan : attenteDe et resumerConversations (lib/assistant/donnees.ts:190-245, en attente
// seulement, 50 au plus), puis le tri de composerBriefing (lib/assistant/briefing.ts:53-55 : les urgentes d'abord, ordre gardé).
// Aucune fenêtre de temps : une demande arrivée la veille à 23 h et jamais lue attend toujours l'artisan.
const L = $('Contexte du passage').first().json.limites;
const comptes = new Set($('Comptes retenus').first().json.comptes.map((c) => c.id));
const demandes = new Map();
for (const i of $('Lire demandes').all()) {
  const l = i.json;
  if (!l || typeof l.id !== 'string' || !comptes.has(l.artisan_id)) continue;
  const cle = l.artisan_id + '|' + l.id;
  if (!demandes.has(cle)) demandes.set(cle, l);
}
const messages = new Map();
for (const i of $('Lire messages').all()) {
  const m = i.json;
  if (!m || typeof m.lead_id !== 'string') continue;
  if (!messages.has(m.lead_id)) messages.set(m.lead_id, []);
  messages.get(m.lead_id).push(m);
}
const attente = (l, siens) => {
  if (l.statut === 'gagne' || l.statut === 'perdu') return null;
  if (siens.some((m) => m.etat === 'proposition')) return 'reponse_a_valider';
  const reels = siens.filter((m) => m.etat == null).sort((a, b) => String(a.sent_at ?? '').localeCompare(String(b.sent_at ?? '')));
  const dernier = reels[reels.length - 1];
  if (dernier && dernier.sens === 'in') return 'client_a_ecrit';
  if (!l.lu_le && (l.statut === 'nouveau' || l.statut === 'en_discussion' || !l.statut)) return 'non_lue';
  return null;
};
const ouvertes = new Map();
for (const p of $('Paquets de demandes ouvertes').all()) {
  const q = p.json;
  if (!q || !comptes.has(q.artisan_id)) continue;
  if (!ouvertes.has(q.artisan_id)) ouvertes.set(q.artisan_id, []);
  for (const id of String(q.lead_ids).split(',')) ouvertes.get(q.artisan_id).push(id);
}
const parCompte = {};
for (const compte of [...ouvertes.keys()].sort()) {
  const enAttente = [];
  for (const id of ouvertes.get(compte)) {
    const l = demandes.get(compte + '|' + id);
    if (!l) throw new Error('demande d’un paquet introuvable');
    if (attente(l, messages.get(id) || [])) enAttente.push(l);
  }
  const triees = enAttente.slice(0, L.conversations).map((l, rang) => ({ l, rang }))
    .sort((a, b) => Number(b.l.urgence === 'urgent') - Number(a.l.urgence === 'urgent') || a.rang - b.rang).map((x) => x.l);
  parCompte[compte] = { nb_en_attente: enAttente.length, liste: triees.map((l) => l.id), urgentes: triees.filter((l) => l.urgence === 'urgent').map((l) => l.id) };
}
return [{ json: { parCompte } }];

// Les devis envoyés sans réponse : la lecture de briefing_du_matin (lib/assistant/executeurs.ts:264 : statut envoyé, envoye_le
// croissant, vides en dernier, 200 au plus ; à égalité, par identifiant), le jour d'envoi compté à Paris (l.277), puis
// composerBriefing (lib/assistant/briefing.ts:40, :58-61 : 7 jours ou plus, le plus ancien d'abord, ordre gardé à égalité).
const C = $('Contexte du passage').first().json;
const comptes = new Set($('Comptes retenus').first().json.comptes.map((c) => c.id));
const format = new Intl.DateTimeFormat('en-CA', { timeZone: 'Europe/Paris', year: 'numeric', month: '2-digit', day: '2-digit' });
const joursEntre = (de, a) => Math.floor((Date.parse(a + 'T00:00:00Z') - Date.parse(de.slice(0, 10) + 'T00:00:00Z')) / 86400000);
const cleTemps = (s) => {
  if (typeof s !== 'string') return null;
  const m = /^(.*T\d{2}:\d{2}:\d{2})(?:\.(\d+))?(.*)$/.exec(s);
  const base = Date.parse(m ? m[1] + m[3] : s);
  if (!Number.isFinite(base)) return null;
  return base * 1000 + (m && m[2] ? Number(m[2].padEnd(6, '0').slice(0, 6)) : 0);
};
const ordre = (a, b) => (a < b ? -1 : a > b ? 1 : 0);
const parCompteLu = new Map();
const vus = new Set();
for (const i of $('Lire devis envoyés').all()) {
  const d = i.json;
  if (!d || typeof d.id !== 'string' || !comptes.has(d.artisan_id) || d.statut !== 'envoye') continue;
  const cle = d.artisan_id + '|' + d.id;
  if (vus.has(cle)) continue;
  vus.add(cle);
  if (!parCompteLu.has(d.artisan_id)) parCompteLu.set(d.artisan_id, []);
  parCompteLu.get(d.artisan_id).push(d);
}
const parCompte = {};
for (const compte of [...parCompteLu.keys()].sort(ordre)) {
  const lus = parCompteLu.get(compte).map((d) => ({ d, t: cleTemps(d.envoye_le) })).sort((a, b) => {
    if (a.t === null || b.t === null) return a.t === b.t ? ordre(a.d.id, b.d.id) : a.t === null ? 1 : -1;
    return a.t - b.t || ordre(a.d.id, b.d.id);
  }).map((x) => x.d).slice(0, C.limites.devis);
  const retenus = lus.map((d, rang) => ({ id: d.id, rang, jours: d.envoye_le ? joursEntre(format.format(new Date(d.envoye_le)), C.jour) : null }))
    .filter((x) => x.jours !== null && x.jours >= C.seuils.devis_sans_reponse_jours)
    .sort((a, b) => b.jours - a.jours || a.rang - b.rang);
  parCompte[compte] = { liste: retenus.map((x) => x.id) };
}
return [{ json: { parCompte } }];

// Les impayés de « Mes chiffres » : la lecture de la route (app/api/compta/tableau/route.ts:19, :37 : 2 000 factures au plus, date
// d'émission décroissante, vides d'abord, puis identifiant), le calcul de l'écran (lib/comptaTableau.ts:211-215 factures comptées,
// :316-337 impayés et leur tri, jours à Paris l.159-169), la liste de resumerFactures (lib/assistant/donnees.ts:111-142, 50 au plus),
// puis les échues de composerBriefing (lib/assistant/briefing.ts:65-68 ; urgentes à 30 jours de retard ou plus).
const C = $('Contexte du passage').first().json;
const comptes = new Set($('Comptes retenus').first().json.comptes.map((c) => c.id));
const format = new Intl.DateTimeFormat('en-CA', { timeZone: 'Europe/Paris', year: 'numeric', month: '2-digit', day: '2-digit' });
const jourDe = (v) => {
  if (typeof v !== 'string') return null;
  if (/^\d{4}-\d{2}-\d{2}$/.test(v)) return v;
  const t = Date.parse(v);
  return Number.isNaN(t) ? null : format.format(new Date(t));
};
const ecartJours = (a, b) => Math.round((Date.UTC(+a.slice(0, 4), +a.slice(5, 7) - 1, +a.slice(8, 10)) - Date.UTC(+b.slice(0, 4), +b.slice(5, 7) - 1, +b.slice(8, 10))) / 86400000);
const centimes = (v) => {
  const n = typeof v === 'number' ? v : typeof v === 'string' ? Number(v.replace(',', '.')) : NaN;
  return Number.isFinite(n) ? Math.round(n * 100) : 0;
};
const ordre = (a, b) => (a < b ? -1 : a > b ? 1 : 0);
const parCompteLu = new Map();
const vus = new Set();
for (const i of $('Lire factures').all()) {
  const f = i.json;
  if (!f || typeof f.id !== 'string' || !comptes.has(f.artisan_id)) continue;
  const cle = f.artisan_id + '|' + f.id;
  if (vus.has(cle)) continue;
  vus.add(cle);
  if (!parCompteLu.has(f.artisan_id)) parCompteLu.set(f.artisan_id, []);
  parCompteLu.get(f.artisan_id).push(f);
}
const jour = C.jour;
const parCompte = {};
for (const compte of [...parCompteLu.keys()].sort(ordre)) {
  const lues = parCompteLu.get(compte).slice().sort((a, b) => {
    const x = typeof a.date_emission === 'string' ? a.date_emission : null, y = typeof b.date_emission === 'string' ? b.date_emission : null;
    if (x === null || y === null) return x === y ? ordre(a.id, b.id) : x === null ? -1 : 1;
    return ordre(y, x) || ordre(a.id, b.id);
  }).slice(0, C.limites.factures);
  const annulees = new Set();
  for (const f of lues) if (typeof f.avoir_de === 'string' && f.avoir_de) annulees.add(f.avoir_de);
  const impayes = [];
  for (const f of lues) {
    if (f.avoir_de || annulees.has(f.id) || f.statut !== 'emise') continue;
    const emission = jourDe(f.date_emission) ?? jour;
    const echeance = jourDe(f.date_echeance);
    impayes.push({ id: f.id, cle: 'presti:' + f.id, montant: centimes(f.total_ttc), emission, joursRetard: echeance && echeance < jour ? ecartJours(jour, echeance) : 0 });
  }
  impayes.sort((a, b) => b.joursRetard - a.joursRetard || a.emission.localeCompare(b.emission) || a.cle.localeCompare(b.cle));
  const echues = impayes.slice(0, C.limites.impayes_listes).filter((i) => i.joursRetard > 0);
  parCompte[compte] = {
    nombre: impayes.length,
    total_centimes: impayes.reduce((s, i) => s + i.montant, 0),
    echues: echues.map((i) => i.id),
    urgentes: echues.filter((i) => i.joursRetard >= C.seuils.impaye_urgent_jours).map((i) => i.id),
  };
}
return [{ json: { parCompte } }];

// Le stock sous le seuil : l'alerte de l'écran Inventaire (app/api/inventaire/route.ts:68-75 : seuil > 0, reste = somme des lieux,
// reste ≤ seuil), épuisé si le reste est à zéro ou moins (lib/assistant/briefing.ts:71). L'écran range par nom (l.63), que ce
// passage ne lit pas : ici, par identifiant (écart déclaré au brief ; le juge compare cette rubrique comme un ensemble).
const comptes = new Set($('Comptes retenus').first().json.comptes.map((c) => c.id));
const ordre = (a, b) => (a < b ? -1 : a > b ? 1 : 0);
const materiaux = new Map();
for (const i of $('Lire matériaux suivis').all()) {
  const m = i.json;
  if (!m || typeof m.id !== 'string' || !comptes.has(m.artisan_id)) continue;
  const cle = m.artisan_id + '|' + m.id;
  if (!materiaux.has(cle)) materiaux.set(cle, { compte: m.artisan_id, id: m.id, seuil: Number(m.seuil_alerte), reste: 0 });
}
const parMateriau = new Map();
for (const m of materiaux.values()) {
  if (!parMateriau.has(m.id)) parMateriau.set(m.id, []);
  parMateriau.get(m.id).push(m);
}
