  sortie.push(Object.assign({}, c, { offre: comptes.get(c.artisan_id).plan, niveau, outil: d.outil, drapeaux: d.drapeaux, reserve: niveau === 3 ? 'pilote' : null }));
}
return [{ json: { constats: sortie } }];

// La seule sortie : une ligne par détecteur, dans l'ordre de l'argent récupéré, puis le total de l'argent qui dort (numéro 0), où chaque
// pièce (facture ou devis) ne compte qu'une fois, à son plus haut montant (M5). Aucune écriture, aucun envoi.
const ctx = $('Contexte du passage').first().json;
const NOMS = { 1: 'facture_echue', 2: 'chantier_a_facturer', 3: 'devis_signe_sans_acompte', 4: 'devis_sans_reponse', 5: 'facture_jamais_envoyee',
  6: 'demande_sans_reponse', 7: 'demande_sans_devis', 8: 'devis_bientot_expire', 9: 'stock_sous_seuil', 10: 'demande_avis',
  11: 'reponse_impaye', 12: 'entretien_a_proposer' };
const ORDRE = [1, 11, 2, 3, 4, 8, 5, 6, 7, 9, 10, 12];
const vues = new Set();
const uniques = ($input.first().json.constats || []).filter((c) => { if (vues.has(c.cle)) return false; vues.add(c.cle); return true; });
const niveaux = (l) => ({ '1': l.filter((c) => c.niveau === 1).length, '2': l.filter((c) => c.niveau === 2).length, '3': l.filter((c) => c.niveau === 3).length });
const montant = (c) => (Number.isFinite(c.montant_centimes) ? c.montant_centimes : 0);
const lignesBilan = ORDRE.map((n) => {
  const l = uniques.filter((c) => c.numero === n);
  return { json: { numero: n, detecteur: NOMS[n], nombre: l.length, montant_total_centimes: l.reduce((s, c) => s + montant(c), 0), par_niveau: niveaux(l), mode: ctx.mode } };
});
const pieces = new Map();
for (const c of uniques) {
  if (!c.argent || !c.argent.id || montant(c) <= 0) continue;
  const k = c.artisan_id + '|' + c.argent.type + '|' + c.argent.id;
  const p = pieces.get(k);
  if (!p || montant(c) > montant(p)) pieces.set(k, c);
}
const total = [...pieces.values()];
lignesBilan.push({ json: { numero: 0, detecteur: 'argent_qui_dort', nombre: total.length, montant_total_centimes: total.reduce((s, c) => s + montant(c), 0), par_niveau: niveaux(total), mode: ctx.mode } });
return lignesBilan;

const ctx = $('Contexte du passage').first().json;
const offres = $('Capacités des offres').first().json;
const S = ctx.seuils;
const JOUR = ctx.jour;
const lignes = (nom) => $(nom).all().map((i) => i.json).filter((r) => r && typeof r === 'object' && Object.keys(r).length > 0);
const jourParis = (v) => {
  if (typeof v !== 'string' || v.length < 10) return null;
  if (v.length === 10) return v;
  const d = new Date(v);
  if (Number.isNaN(d.getTime())) return null;
  const p = {};
  for (const x of new Intl.DateTimeFormat('en-GB', { timeZone: 'Europe/Paris', year: 'numeric', month: '2-digit', day: '2-digit' }).formatToParts(d)) p[x.type] = x.value;
  return p.year + '-' + p.month + '-' + p.day;
};
const ecart = (a, b) => Math.round((Date.parse(a + 'T00:00:00Z') - Date.parse(b + 'T00:00:00Z')) / 86400000);
const centimes = (v) => { const n = Number(v); return Number.isFinite(n) ? Math.round(n * 100) : 0; };
// M2 (032-010) : toute jointure entre deux lectures passe par le compte ET l'identifiant, jamais par l'identifiant seul.
const paire = (artisanId, id) => artisanId + '|' + id;
const comptes = new Map(lignes('Lire comptes').map((a) => [a.id, a]));
const caps = (artisanId) => { const c = comptes.get(artisanId); return c && offres.capacites[c.plan] ? offres.capacites[c.plan] : null; };
const aLaCapacite = (artisanId, cap) => { const l = caps(artisanId); return !!l && l.includes(cap); };
const avant = $input.first().json.constats || [];
const nouveaux = [];
// `argent` : la pièce dont l'argent dort (facture ou devis), pour un total qui ne compte jamais deux fois la même (M5).
const constat = (numero, detecteur, artisanId, typeObjet, idObjet, etape, montant, jours, argent) => {
  nouveaux.push({ numero, detecteur, cle: detecteur + ':' + idObjet + ':' + etape, artisan_id: artisanId, objet: { type: typeObjet, id: idObjet }, etape, montant_centimes: montant, jours, argent: argent || null });
};
// n° 11 — relance d'impayé arrêtée par une réponse du client (plan §9, n° 11 ; §0 bis, rang 1) : relances_impayes_arrets.raison
// « reponse_client », reprise_le vide (0159_relances_impayes.sql:59-66), facture du même compte encore due (émise, ni payée ni avoir).
// Jamais messages : n8n ne sait pas ce que le client a dit ; la carte le demande à l'artisan, qui range le motif d'un geste (L13).
// L'étape est le jour de l'arrêt : un nouvel arrêt après une reprise donne une clé neuve.
const factures = new Map(lignes('Lire factures').map((f) => [paire(f.artisan_id, f.id), f]));
for (const a of lignes('Lire arrets de relance')) {
  if (a.raison !== 'reponse_client' || a.reprise_le) continue;
  if (!aLaCapacite(a.artisan_id, 'factures.relances')) continue;
  const f = factures.get(paire(a.artisan_id, a.facture_id));
  if (!f || f.statut !== 'emise' || f.payee_le || f.avoir_de) continue;
  const m = centimes(f.total_ttc);
  if (m <= 0) continue;
  const le = jourParis(a.le);
  if (!le) continue;
  constat(11, 'reponse_impaye', a.artisan_id, 'facture', f.id, 'r' + le.replace(/-/g, ''), m, Math.max(0, ecart(JOUR, le)), { type: 'facture', id: f.id });
}
return [{ json: { constats: avant.concat(nouveaux) } }];

